-- EnglishwithMikey practice v2: 20 topics x 30 sentences.
-- Run the ENTIRE file in Supabase SQL Editor. No schema or RLS changes.
-- Preserves existing sentence IDs, completed learning_progress, XP and publish status.
-- Creates the 20 topic lessons as Draft if the original import has not been run.
-- Lesson 1 and Lesson 2 are never replaced or expanded by this script.
BEGIN;
DO $import$
DECLARE
  pack_id constant text := 'mikey-a1-topics-v1';
  lesson_record jsonb;
  sentence_record jsonb;
  imported_lesson_id bigint;
  previous_description text;
  previous_count integer;
  added integer := 0;
  skipped integer := 0;
  sentence_columns text := '';
  sentence_values text := '';
  optional_column text;
  lesson_data jsonb := $topic_data$
[
{"key": "a1-topic-03", "number": 3, "title": "Lesson 3: My Family", "title_vi": "Gia đình của tôi", "description": "Bài 3: Gia đình của tôi. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về gia đình của tôi; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng my/your và câu This is… để giới thiệu người thân.", "vocabulary_notes": "family: gia đình; mother: mẹ; father: bố; sister: chị/em gái; brother: anh/em trai", "content": "My Family – Gia đình của tôi\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng my/your và câu This is… để giới thiệu người thân.\n\nTừ vựng: family: gia đình; mother: mẹ; father: bố; sister: chị/em gái; brother: anh/em trai\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "This is my family.", "vietnamese": "Đây là gia đình tôi.", "position": 1}, {"english": "This is my mother.", "vietnamese": "Đây là mẹ tôi.", "position": 2}, {"english": "This is my father.", "vietnamese": "Đây là bố tôi.", "position": 3}, {"english": "I have one sister.", "vietnamese": "Tôi có một chị gái.", "position": 4}, {"english": "I have two brothers.", "vietnamese": "Tôi có hai anh trai.", "position": 5}, {"english": "My mother is a teacher.", "vietnamese": "Mẹ tôi là giáo viên.", "position": 6}, {"english": "My father works in a shop.", "vietnamese": "Bố tôi làm việc ở một cửa hàng.", "position": 7}, {"english": "We live in Hanoi.", "vietnamese": "Chúng tôi sống ở Hà Nội.", "position": 8}, {"english": "Do you have any brothers or sisters?", "vietnamese": "Bạn có anh chị em không?", "position": 9}, {"english": "I love my family.", "vietnamese": "Tôi yêu gia đình mình.", "position": 10}]},
{"key": "a1-topic-04", "number": 4, "title": "Lesson 4: My Home", "title_vi": "Ngôi nhà của tôi", "description": "Bài 4: Ngôi nhà của tôi. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về ngôi nhà của tôi; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng there is + danh từ số ít và there are + danh từ số nhiều để mô tả nhà.", "vocabulary_notes": "home: nhà; bedroom: phòng ngủ; kitchen: nhà bếp; table: bàn; chair: ghế", "content": "My Home – Ngôi nhà của tôi\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng there is + danh từ số ít và there are + danh từ số nhiều để mô tả nhà.\n\nTừ vựng: home: nhà; bedroom: phòng ngủ; kitchen: nhà bếp; table: bàn; chair: ghế\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "I live in a small house.", "vietnamese": "Tôi sống trong một ngôi nhà nhỏ.", "position": 1}, {"english": "There are two bedrooms.", "vietnamese": "Có hai phòng ngủ.", "position": 2}, {"english": "There is a kitchen.", "vietnamese": "Có một nhà bếp.", "position": 3}, {"english": "My room is upstairs.", "vietnamese": "Phòng tôi ở tầng trên.", "position": 4}, {"english": "The bathroom is next to my room.", "vietnamese": "Phòng tắm ở cạnh phòng tôi.", "position": 5}, {"english": "There is a table in the kitchen.", "vietnamese": "Có một chiếc bàn trong bếp.", "position": 6}, {"english": "There are four chairs.", "vietnamese": "Có bốn chiếc ghế.", "position": 7}, {"english": "My bag is on the chair.", "vietnamese": "Túi của tôi ở trên ghế.", "position": 8}, {"english": "The keys are under the table.", "vietnamese": "Chìa khóa ở dưới bàn.", "position": 9}, {"english": "I like my home.", "vietnamese": "Tôi thích ngôi nhà của mình.", "position": 10}]},
{"key": "a1-topic-05", "number": 5, "title": "Lesson 5: Numbers and Age", "title_vi": "Số đếm và tuổi", "description": "Bài 5: Số đếm và tuổi. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về số đếm và tuổi; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Hỏi tuổi bằng How old are you? Trả lời bằng I am + số tuổi.", "vocabulary_notes": "number: số; age: tuổi; year: năm; old: có tuổi; phone number: số điện thoại", "content": "Numbers and Age – Số đếm và tuổi\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Hỏi tuổi bằng How old are you? Trả lời bằng I am + số tuổi.\n\nTừ vựng: number: số; age: tuổi; year: năm; old: có tuổi; phone number: số điện thoại\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "How old are you?", "vietnamese": "Bạn bao nhiêu tuổi?", "position": 1}, {"english": "I am twenty years old.", "vietnamese": "Tôi hai mươi tuổi.", "position": 2}, {"english": "My sister is eighteen.", "vietnamese": "Chị gái tôi mười tám tuổi.", "position": 3}, {"english": "There are ten students.", "vietnamese": "Có mười học sinh.", "position": 4}, {"english": "I have three books.", "vietnamese": "Tôi có ba quyển sách.", "position": 5}, {"english": "Please count from one to ten.", "vietnamese": "Hãy đếm từ một đến mười.", "position": 6}, {"english": "What is your phone number?", "vietnamese": "Số điện thoại của bạn là gì?", "position": 7}, {"english": "Please say the number again.", "vietnamese": "Vui lòng đọc lại số đó.", "position": 8}, {"english": "Is this number correct?", "vietnamese": "Số này có đúng không?", "position": 9}, {"english": "Yes, that is correct.", "vietnamese": "Vâng, đúng rồi.", "position": 10}]},
{"key": "a1-topic-06", "number": 6, "title": "Lesson 6: Time and Days", "title_vi": "Giờ và các ngày trong tuần", "description": "Bài 6: Giờ và các ngày trong tuần. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về giờ và các ngày trong tuần; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng at trước giờ, on trước ngày trong tuần; hỏi giờ bằng What time is it?", "vocabulary_notes": "time: thời gian; Monday: thứ Hai; Friday: thứ Sáu; today: hôm nay; tomorrow: ngày mai", "content": "Time and Days – Giờ và các ngày trong tuần\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng at trước giờ, on trước ngày trong tuần; hỏi giờ bằng What time is it?\n\nTừ vựng: time: thời gian; Monday: thứ Hai; Friday: thứ Sáu; today: hôm nay; tomorrow: ngày mai\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "What time is it?", "vietnamese": "Bây giờ là mấy giờ?", "position": 1}, {"english": "It is nine o'clock.", "vietnamese": "Bây giờ là chín giờ.", "position": 2}, {"english": "It is half past seven.", "vietnamese": "Bây giờ là bảy giờ rưỡi.", "position": 3}, {"english": "What day is it today?", "vietnamese": "Hôm nay là thứ mấy?", "position": 4}, {"english": "Today is Monday.", "vietnamese": "Hôm nay là thứ Hai.", "position": 5}, {"english": "Tomorrow is Tuesday.", "vietnamese": "Ngày mai là thứ Ba.", "position": 6}, {"english": "The class starts at eight.", "vietnamese": "Lớp học bắt đầu lúc tám giờ.", "position": 7}, {"english": "I study English on Fridays.", "vietnamese": "Tôi học tiếng Anh vào các ngày thứ Sáu.", "position": 8}, {"english": "Are you free on Sunday?", "vietnamese": "Bạn có rảnh vào Chủ nhật không?", "position": 9}, {"english": "See you on Saturday.", "vietnamese": "Hẹn gặp bạn vào thứ Bảy.", "position": 10}]},
{"key": "a1-topic-07", "number": 7, "title": "Lesson 7: Food and Drinks", "title_vi": "Đồ ăn và thức uống", "description": "Bài 7: Đồ ăn và thức uống. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về đồ ăn và thức uống; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng I like/I do not like để nói sở thích; dùng some với lượng không xác định.", "vocabulary_notes": "food: đồ ăn; water: nước; rice: cơm; chicken: thịt gà; vegetables: rau", "content": "Food and Drinks – Đồ ăn và thức uống\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng I like/I do not like để nói sở thích; dùng some với lượng không xác định.\n\nTừ vựng: food: đồ ăn; water: nước; rice: cơm; chicken: thịt gà; vegetables: rau\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "I like rice and chicken.", "vietnamese": "Tôi thích cơm và thịt gà.", "position": 1}, {"english": "I eat vegetables every day.", "vietnamese": "Tôi ăn rau mỗi ngày.", "position": 2}, {"english": "I drink water with my lunch.", "vietnamese": "Tôi uống nước trong bữa trưa.", "position": 3}, {"english": "Do you like coffee?", "vietnamese": "Bạn có thích cà phê không?", "position": 4}, {"english": "I prefer tea.", "vietnamese": "Tôi thích trà hơn.", "position": 5}, {"english": "I do not like milk.", "vietnamese": "Tôi không thích sữa.", "position": 6}, {"english": "Would you like some juice?", "vietnamese": "Bạn có muốn uống nước ép không?", "position": 7}, {"english": "Yes, please.", "vietnamese": "Vâng, cho tôi xin.", "position": 8}, {"english": "No, thank you.", "vietnamese": "Không, cảm ơn bạn.", "position": 9}, {"english": "This soup is very good.", "vietnamese": "Món súp này rất ngon.", "position": 10}]},
{"key": "a1-topic-08", "number": 8, "title": "Lesson 8: At a Restaurant", "title_vi": "Tại nhà hàng", "description": "Bài 8: Tại nhà hàng. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về tại nhà hàng; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng I would like… để gọi món lịch sự; Can I have…? để yêu cầu.", "vocabulary_notes": "menu: thực đơn; order: gọi món; soup: súp; bill: hóa đơn; delicious: ngon", "content": "At a Restaurant – Tại nhà hàng\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng I would like… để gọi món lịch sự; Can I have…? để yêu cầu.\n\nTừ vựng: menu: thực đơn; order: gọi món; soup: súp; bill: hóa đơn; delicious: ngon\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "A table for two, please.", "vietnamese": "Cho tôi một bàn hai người.", "position": 1}, {"english": "Can I see the menu, please?", "vietnamese": "Cho tôi xem thực đơn được không?", "position": 2}, {"english": "I would like some chicken.", "vietnamese": "Tôi muốn gọi một phần thịt gà.", "position": 3}, {"english": "Can I have some water, please?", "vietnamese": "Cho tôi xin ít nước được không?", "position": 4}, {"english": "What would you like to drink?", "vietnamese": "Bạn muốn uống gì?", "position": 5}, {"english": "I would like a cup of tea.", "vietnamese": "Tôi muốn một tách trà.", "position": 6}, {"english": "Is this dish spicy?", "vietnamese": "Món này có cay không?", "position": 7}, {"english": "Please do not add any chilli.", "vietnamese": "Vui lòng đừng cho ớt.", "position": 8}, {"english": "The food is delicious.", "vietnamese": "Đồ ăn rất ngon.", "position": 9}, {"english": "Can I have the bill, please?", "vietnamese": "Cho tôi xin hóa đơn được không?", "position": 10}]},
{"key": "a1-topic-09", "number": 9, "title": "Lesson 9: Shopping and Prices", "title_vi": "Mua sắm và giá cả", "description": "Bài 9: Mua sắm và giá cả. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về mua sắm và giá cả; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Hỏi giá bằng How much is…? Dùng this cho vật ở gần, that cho vật ở xa.", "vocabulary_notes": "price: giá; buy: mua; cash: tiền mặt; card: thẻ; expensive: đắt", "content": "Shopping and Prices – Mua sắm và giá cả\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Hỏi giá bằng How much is…? Dùng this cho vật ở gần, that cho vật ở xa.\n\nTừ vựng: price: giá; buy: mua; cash: tiền mặt; card: thẻ; expensive: đắt\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "How much is this bag?", "vietnamese": "Chiếc túi này giá bao nhiêu?", "position": 1}, {"english": "It is two hundred thousand dong.", "vietnamese": "Giá của nó là hai trăm nghìn đồng.", "position": 2}, {"english": "That is too expensive.", "vietnamese": "Giá đó đắt quá.", "position": 3}, {"english": "Do you have a cheaper one?", "vietnamese": "Bạn có loại rẻ hơn không?", "position": 4}, {"english": "I am just looking, thank you.", "vietnamese": "Tôi chỉ xem thôi, cảm ơn bạn.", "position": 5}, {"english": "I would like to buy this.", "vietnamese": "Tôi muốn mua món này.", "position": 6}, {"english": "Can I pay by card?", "vietnamese": "Tôi có thể thanh toán bằng thẻ không?", "position": 7}, {"english": "I will pay in cash.", "vietnamese": "Tôi sẽ trả bằng tiền mặt.", "position": 8}, {"english": "Can I have a receipt, please?", "vietnamese": "Cho tôi xin biên lai được không?", "position": 9}, {"english": "Thank you for your help.", "vietnamese": "Cảm ơn bạn đã giúp đỡ.", "position": 10}]},
{"key": "a1-topic-10", "number": 10, "title": "Lesson 10: Clothes and Colours", "title_vi": "Quần áo và màu sắc", "description": "Bài 10: Quần áo và màu sắc. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về quần áo và màu sắc; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng tính từ màu sắc trước danh từ: a blue shirt; hỏi lựa chọn bằng What colour…?", "vocabulary_notes": "shirt: áo sơ mi; shoes: giày; size: cỡ; blue: xanh dương; red: đỏ", "content": "Clothes and Colours – Quần áo và màu sắc\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng tính từ màu sắc trước danh từ: a blue shirt; hỏi lựa chọn bằng What colour…?\n\nTừ vựng: shirt: áo sơ mi; shoes: giày; size: cỡ; blue: xanh dương; red: đỏ\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "I need a new shirt.", "vietnamese": "Tôi cần một chiếc áo sơ mi mới.", "position": 1}, {"english": "I like the blue one.", "vietnamese": "Tôi thích chiếc màu xanh dương.", "position": 2}, {"english": "What colour do you like?", "vietnamese": "Bạn thích màu gì?", "position": 3}, {"english": "I like red.", "vietnamese": "Tôi thích màu đỏ.", "position": 4}, {"english": "What size do you need?", "vietnamese": "Bạn cần cỡ nào?", "position": 5}, {"english": "I need a medium.", "vietnamese": "Tôi cần cỡ vừa.", "position": 6}, {"english": "Can I try this on?", "vietnamese": "Tôi có thể thử chiếc này không?", "position": 7}, {"english": "Where is the fitting room?", "vietnamese": "Phòng thử đồ ở đâu?", "position": 8}, {"english": "These shoes are too small.", "vietnamese": "Đôi giày này nhỏ quá.", "position": 9}, {"english": "This jacket fits well.", "vietnamese": "Chiếc áo khoác này vừa vặn.", "position": 10}]},
{"key": "a1-topic-11", "number": 11, "title": "Lesson 11: Asking for Directions", "title_vi": "Hỏi đường", "description": "Bài 11: Hỏi đường. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về hỏi đường; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng Where is…? để hỏi địa điểm; dùng động từ đầu câu để chỉ đường.", "vocabulary_notes": "left: trái; right: phải; straight: thẳng; near: gần; opposite: đối diện", "content": "Asking for Directions – Hỏi đường\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng Where is…? để hỏi địa điểm; dùng động từ đầu câu để chỉ đường.\n\nTừ vựng: left: trái; right: phải; straight: thẳng; near: gần; opposite: đối diện\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "Excuse me, where is the bank?", "vietnamese": "Xin lỗi, ngân hàng ở đâu?", "position": 1}, {"english": "Go straight ahead.", "vietnamese": "Đi thẳng về phía trước.", "position": 2}, {"english": "Turn left at the traffic lights.", "vietnamese": "Rẽ trái ở chỗ đèn giao thông.", "position": 3}, {"english": "Turn right at the next street.", "vietnamese": "Rẽ phải ở đường tiếp theo.", "position": 4}, {"english": "The bank is next to the supermarket.", "vietnamese": "Ngân hàng ở cạnh siêu thị.", "position": 5}, {"english": "It is opposite the hospital.", "vietnamese": "Nó ở đối diện bệnh viện.", "position": 6}, {"english": "Is it far from here?", "vietnamese": "Chỗ đó có xa đây không?", "position": 7}, {"english": "It is about five minutes on foot.", "vietnamese": "Đi bộ mất khoảng năm phút.", "position": 8}, {"english": "Can you show me on the map?", "vietnamese": "Bạn có thể chỉ trên bản đồ cho tôi không?", "position": 9}, {"english": "Thank you. I understand now.", "vietnamese": "Cảm ơn bạn. Bây giờ tôi hiểu rồi.", "position": 10}]},
{"key": "a1-topic-12", "number": 12, "title": "Lesson 12: Getting Around Town", "title_vi": "Đi lại trong thành phố", "description": "Bài 12: Đi lại trong thành phố. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về đi lại trong thành phố; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng by + phương tiện để nói cách đi lại; dùng How do you get to…? để hỏi.", "vocabulary_notes": "bus: xe buýt; train: tàu; ticket: vé; station: nhà ga; on foot: đi bộ", "content": "Getting Around Town – Đi lại trong thành phố\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng by + phương tiện để nói cách đi lại; dùng How do you get to…? để hỏi.\n\nTừ vựng: bus: xe buýt; train: tàu; ticket: vé; station: nhà ga; on foot: đi bộ\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "I go to work by bus.", "vietnamese": "Tôi đi làm bằng xe buýt.", "position": 1}, {"english": "How do you get to school?", "vietnamese": "Bạn đến trường bằng cách nào?", "position": 2}, {"english": "I walk to school.", "vietnamese": "Tôi đi bộ đến trường.", "position": 3}, {"english": "Where is the bus stop?", "vietnamese": "Trạm xe buýt ở đâu?", "position": 4}, {"english": "Does this bus go to the city centre?", "vietnamese": "Xe buýt này có đến trung tâm thành phố không?", "position": 5}, {"english": "I need a ticket to Hanoi.", "vietnamese": "Tôi cần một vé đi Hà Nội.", "position": 6}, {"english": "How much is a ticket?", "vietnamese": "Một vé giá bao nhiêu?", "position": 7}, {"english": "What time does the train leave?", "vietnamese": "Tàu khởi hành lúc mấy giờ?", "position": 8}, {"english": "Please stop here.", "vietnamese": "Vui lòng dừng ở đây.", "position": 9}, {"english": "I would like to get off here.", "vietnamese": "Tôi muốn xuống ở đây.", "position": 10}]},
{"key": "a1-topic-13", "number": 13, "title": "Lesson 13: The Weather", "title_vi": "Thời tiết", "description": "Bài 13: Thời tiết. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về thời tiết; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng It is + tính từ để mô tả thời tiết; hỏi bằng What is the weather like?", "vocabulary_notes": "weather: thời tiết; sunny: có nắng; rainy: có mưa; cold: lạnh; umbrella: ô", "content": "The Weather – Thời tiết\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng It is + tính từ để mô tả thời tiết; hỏi bằng What is the weather like?\n\nTừ vựng: weather: thời tiết; sunny: có nắng; rainy: có mưa; cold: lạnh; umbrella: ô\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "What is the weather like today?", "vietnamese": "Hôm nay thời tiết thế nào?", "position": 1}, {"english": "It is sunny.", "vietnamese": "Trời có nắng.", "position": 2}, {"english": "It is very hot today.", "vietnamese": "Hôm nay trời rất nóng.", "position": 3}, {"english": "It is cold this morning.", "vietnamese": "Sáng nay trời lạnh.", "position": 4}, {"english": "It is raining now.", "vietnamese": "Bây giờ trời đang mưa.", "position": 5}, {"english": "Do you have an umbrella?", "vietnamese": "Bạn có ô không?", "position": 6}, {"english": "I need a warm coat.", "vietnamese": "Tôi cần một chiếc áo khoác ấm.", "position": 7}, {"english": "It is windy outside.", "vietnamese": "Bên ngoài trời có gió.", "position": 8}, {"english": "I like cool weather.", "vietnamese": "Tôi thích thời tiết mát mẻ.", "position": 9}, {"english": "Let us stay inside.", "vietnamese": "Chúng ta hãy ở trong nhà.", "position": 10}]},
{"key": "a1-topic-14", "number": 14, "title": "Lesson 14: Hobbies and Free Time", "title_vi": "Sở thích và thời gian rảnh", "description": "Bài 14: Sở thích và thời gian rảnh. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về sở thích và thời gian rảnh; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng like + V-ing để nói sở thích; dùng can + động từ nguyên mẫu để nói khả năng.", "vocabulary_notes": "hobby: sở thích; read: đọc; swim: bơi; music: âm nhạc; free time: thời gian rảnh", "content": "Hobbies and Free Time – Sở thích và thời gian rảnh\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng like + V-ing để nói sở thích; dùng can + động từ nguyên mẫu để nói khả năng.\n\nTừ vựng: hobby: sở thích; read: đọc; swim: bơi; music: âm nhạc; free time: thời gian rảnh\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "What do you do in your free time?", "vietnamese": "Bạn làm gì trong thời gian rảnh?", "position": 1}, {"english": "I like reading books.", "vietnamese": "Tôi thích đọc sách.", "position": 2}, {"english": "I listen to music every day.", "vietnamese": "Tôi nghe nhạc mỗi ngày.", "position": 3}, {"english": "Do you like playing football?", "vietnamese": "Bạn có thích chơi bóng đá không?", "position": 4}, {"english": "I play football on Sundays.", "vietnamese": "Tôi chơi bóng đá vào các ngày Chủ nhật.", "position": 5}, {"english": "Can you swim?", "vietnamese": "Bạn có biết bơi không?", "position": 6}, {"english": "Yes, I can swim.", "vietnamese": "Có, tôi biết bơi.", "position": 7}, {"english": "I enjoy cooking.", "vietnamese": "Tôi thích nấu ăn.", "position": 8}, {"english": "My hobby is taking photos.", "vietnamese": "Sở thích của tôi là chụp ảnh.", "position": 9}, {"english": "Would you like to join us?", "vietnamese": "Bạn có muốn tham gia cùng chúng tôi không?", "position": 10}]},
{"key": "a1-topic-15", "number": 15, "title": "Lesson 15: Jobs and Workplaces", "title_vi": "Nghề nghiệp và nơi làm việc", "description": "Bài 15: Nghề nghiệp và nơi làm việc. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về nghề nghiệp và nơi làm việc; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Hỏi nghề bằng What do you do? Dùng a/an trước tên nghề số ít.", "vocabulary_notes": "job: nghề nghiệp; office: văn phòng; teacher: giáo viên; nurse: y tá; colleague: đồng nghiệp", "content": "Jobs and Workplaces – Nghề nghiệp và nơi làm việc\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Hỏi nghề bằng What do you do? Dùng a/an trước tên nghề số ít.\n\nTừ vựng: job: nghề nghiệp; office: văn phòng; teacher: giáo viên; nurse: y tá; colleague: đồng nghiệp\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "What do you do?", "vietnamese": "Bạn làm nghề gì?", "position": 1}, {"english": "I am a teacher.", "vietnamese": "Tôi là giáo viên.", "position": 2}, {"english": "She is a nurse.", "vietnamese": "Cô ấy là y tá.", "position": 3}, {"english": "He is an engineer.", "vietnamese": "Anh ấy là kỹ sư.", "position": 4}, {"english": "Where do you work?", "vietnamese": "Bạn làm việc ở đâu?", "position": 5}, {"english": "I work in an office.", "vietnamese": "Tôi làm việc ở văn phòng.", "position": 6}, {"english": "My office is near my home.", "vietnamese": "Văn phòng của tôi ở gần nhà.", "position": 7}, {"english": "I start work at nine.", "vietnamese": "Tôi bắt đầu làm việc lúc chín giờ.", "position": 8}, {"english": "I finish work at five.", "vietnamese": "Tôi kết thúc công việc lúc năm giờ.", "position": 9}, {"english": "My colleagues are friendly.", "vietnamese": "Đồng nghiệp của tôi rất thân thiện.", "position": 10}]},
{"key": "a1-topic-16", "number": 16, "title": "Lesson 16: In the Classroom", "title_vi": "Trong lớp học", "description": "Bài 16: Trong lớp học. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về trong lớp học; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng Can you…? để đề nghị hỗ trợ; dùng Please + động từ để đưa yêu cầu lịch sự.", "vocabulary_notes": "classroom: lớp học; repeat: nhắc lại; spell: đánh vần; question: câu hỏi; slowly: chậm", "content": "In the Classroom – Trong lớp học\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng Can you…? để đề nghị hỗ trợ; dùng Please + động từ để đưa yêu cầu lịch sự.\n\nTừ vựng: classroom: lớp học; repeat: nhắc lại; spell: đánh vần; question: câu hỏi; slowly: chậm\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "Please open your book.", "vietnamese": "Vui lòng mở sách ra.", "position": 1}, {"english": "Please listen carefully.", "vietnamese": "Vui lòng lắng nghe kỹ.", "position": 2}, {"english": "Can you repeat that, please?", "vietnamese": "Bạn có thể nhắc lại điều đó không?", "position": 3}, {"english": "Please speak more slowly.", "vietnamese": "Vui lòng nói chậm hơn.", "position": 4}, {"english": "I do not understand this word.", "vietnamese": "Tôi không hiểu từ này.", "position": 5}, {"english": "What does this word mean?", "vietnamese": "Từ này có nghĩa là gì?", "position": 6}, {"english": "How do you spell your name?", "vietnamese": "Bạn đánh vần tên mình như thế nào?", "position": 7}, {"english": "Can I ask a question?", "vietnamese": "Tôi có thể hỏi một câu không?", "position": 8}, {"english": "May I come in?", "vietnamese": "Em có thể vào lớp không?", "position": 9}, {"english": "Thank you for explaining.", "vietnamese": "Cảm ơn bạn đã giải thích.", "position": 10}]},
{"key": "a1-topic-17", "number": 17, "title": "Lesson 17: Health and the Body", "title_vi": "Sức khỏe và cơ thể", "description": "Bài 17: Sức khỏe và cơ thể. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về sức khỏe và cơ thể; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng I have + triệu chứng; dùng My + bộ phận cơ thể + hurts để nói chỗ đau.", "vocabulary_notes": "headache: đau đầu; sore throat: đau họng; fever: sốt; doctor: bác sĩ; rest: nghỉ ngơi", "content": "Health and the Body – Sức khỏe và cơ thể\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng I have + triệu chứng; dùng My + bộ phận cơ thể + hurts để nói chỗ đau.\n\nTừ vựng: headache: đau đầu; sore throat: đau họng; fever: sốt; doctor: bác sĩ; rest: nghỉ ngơi\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "I do not feel well.", "vietnamese": "Tôi thấy không khỏe.", "position": 1}, {"english": "I have a headache.", "vietnamese": "Tôi bị đau đầu.", "position": 2}, {"english": "I have a sore throat.", "vietnamese": "Tôi bị đau họng.", "position": 3}, {"english": "My stomach hurts.", "vietnamese": "Tôi bị đau bụng.", "position": 4}, {"english": "Do you have a fever?", "vietnamese": "Bạn có bị sốt không?", "position": 5}, {"english": "I need to see a doctor.", "vietnamese": "Tôi cần gặp bác sĩ.", "position": 6}, {"english": "Where is the nearest clinic?", "vietnamese": "Phòng khám gần nhất ở đâu?", "position": 7}, {"english": "I need some water.", "vietnamese": "Tôi cần ít nước.", "position": 8}, {"english": "I want to rest.", "vietnamese": "Tôi muốn nghỉ ngơi.", "position": 9}, {"english": "I feel better now.", "vietnamese": "Bây giờ tôi thấy đỡ hơn.", "position": 10}]},
{"key": "a1-topic-18", "number": 18, "title": "Lesson 18: Feelings and Emotions", "title_vi": "Cảm xúc", "description": "Bài 18: Cảm xúc. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về cảm xúc; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng be + tính từ để nói cảm xúc; dùng because để nêu lý do ngắn.", "vocabulary_notes": "happy: vui; sad: buồn; tired: mệt; worried: lo lắng; excited: hào hứng", "content": "Feelings and Emotions – Cảm xúc\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng be + tính từ để nói cảm xúc; dùng because để nêu lý do ngắn.\n\nTừ vựng: happy: vui; sad: buồn; tired: mệt; worried: lo lắng; excited: hào hứng\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "How do you feel today?", "vietnamese": "Hôm nay bạn cảm thấy thế nào?", "position": 1}, {"english": "I feel happy.", "vietnamese": "Tôi cảm thấy vui.", "position": 2}, {"english": "I am a little tired.", "vietnamese": "Tôi hơi mệt.", "position": 3}, {"english": "Are you worried?", "vietnamese": "Bạn có đang lo lắng không?", "position": 4}, {"english": "I am worried about my exam.", "vietnamese": "Tôi lo lắng về kỳ thi của mình.", "position": 5}, {"english": "She is excited about the trip.", "vietnamese": "Cô ấy hào hứng với chuyến đi.", "position": 6}, {"english": "I am sad because my friend is leaving.", "vietnamese": "Tôi buồn vì bạn tôi sắp đi xa.", "position": 7}, {"english": "I feel better after a walk.", "vietnamese": "Tôi cảm thấy tốt hơn sau khi đi bộ.", "position": 8}, {"english": "Do you want to talk?", "vietnamese": "Bạn có muốn nói chuyện không?", "position": 9}, {"english": "I am here to listen.", "vietnamese": "Tôi ở đây để lắng nghe.", "position": 10}]},
{"key": "a1-topic-19", "number": 19, "title": "Lesson 19: Weekend Plans", "title_vi": "Kế hoạch cuối tuần", "description": "Bài 19: Kế hoạch cuối tuần. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về kế hoạch cuối tuần; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng be going to + động từ nguyên mẫu để nói dự định; dùng Let us… để gợi ý.", "vocabulary_notes": "weekend: cuối tuần; visit: thăm; park: công viên; plan: kế hoạch; tomorrow: ngày mai", "content": "Weekend Plans – Kế hoạch cuối tuần\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng be going to + động từ nguyên mẫu để nói dự định; dùng Let us… để gợi ý.\n\nTừ vựng: weekend: cuối tuần; visit: thăm; park: công viên; plan: kế hoạch; tomorrow: ngày mai\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "What are you going to do this weekend?", "vietnamese": "Bạn định làm gì vào cuối tuần này?", "position": 1}, {"english": "I am going to visit my parents.", "vietnamese": "Tôi định đến thăm bố mẹ.", "position": 2}, {"english": "We are going to have lunch together.", "vietnamese": "Chúng tôi định ăn trưa cùng nhau.", "position": 3}, {"english": "Are you free tomorrow?", "vietnamese": "Ngày mai bạn có rảnh không?", "position": 4}, {"english": "Let us go to the park.", "vietnamese": "Chúng ta hãy đến công viên.", "position": 5}, {"english": "That sounds good.", "vietnamese": "Nghe hay đấy.", "position": 6}, {"english": "What time shall we meet?", "vietnamese": "Chúng ta gặp nhau lúc mấy giờ?", "position": 7}, {"english": "Let us meet at ten.", "vietnamese": "Chúng ta hãy gặp nhau lúc mười giờ.", "position": 8}, {"english": "I cannot come on Saturday.", "vietnamese": "Tôi không thể đến vào thứ Bảy.", "position": 9}, {"english": "See you on Sunday.", "vietnamese": "Hẹn gặp bạn vào Chủ nhật.", "position": 10}]},
{"key": "a1-topic-20", "number": 20, "title": "Lesson 20: Travel Essentials", "title_vi": "Giao tiếp khi đi du lịch", "description": "Bài 20: Giao tiếp khi đi du lịch. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về giao tiếp khi đi du lịch; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng I need… để nói nhu cầu và Where can I…? để hỏi nơi thực hiện việc gì.", "vocabulary_notes": "passport: hộ chiếu; airport: sân bay; flight: chuyến bay; luggage: hành lý; gate: cửa ra máy bay", "content": "Travel Essentials – Giao tiếp khi đi du lịch\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng I need… để nói nhu cầu và Where can I…? để hỏi nơi thực hiện việc gì.\n\nTừ vựng: passport: hộ chiếu; airport: sân bay; flight: chuyến bay; luggage: hành lý; gate: cửa ra máy bay\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "Where is the airport?", "vietnamese": "Sân bay ở đâu?", "position": 1}, {"english": "I have my passport.", "vietnamese": "Tôi có mang hộ chiếu.", "position": 2}, {"english": "Where can I check in?", "vietnamese": "Tôi có thể làm thủ tục ở đâu?", "position": 3}, {"english": "Here is my ticket.", "vietnamese": "Đây là vé của tôi.", "position": 4}, {"english": "I have one suitcase.", "vietnamese": "Tôi có một va li.", "position": 5}, {"english": "What is the gate number?", "vietnamese": "Cửa ra máy bay là số mấy?", "position": 6}, {"english": "My flight leaves at two.", "vietnamese": "Chuyến bay của tôi khởi hành lúc hai giờ.", "position": 7}, {"english": "Where can I collect my luggage?", "vietnamese": "Tôi có thể nhận hành lý ở đâu?", "position": 8}, {"english": "I am here on holiday.", "vietnamese": "Tôi đến đây để nghỉ dưỡng.", "position": 9}, {"english": "I need a map of the city.", "vietnamese": "Tôi cần một bản đồ thành phố.", "position": 10}]},
{"key": "a1-topic-21", "number": 21, "title": "Lesson 21: At a Hotel", "title_vi": "Tại khách sạn", "description": "Bài 21: Tại khách sạn. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về tại khách sạn; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng I have… để xác nhận đặt phòng; dùng Is there…? để hỏi tiện ích.", "vocabulary_notes": "reservation: đặt phòng; room: phòng; key: chìa khóa; breakfast: bữa sáng; check out: trả phòng", "content": "At a Hotel – Tại khách sạn\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng I have… để xác nhận đặt phòng; dùng Is there…? để hỏi tiện ích.\n\nTừ vựng: reservation: đặt phòng; room: phòng; key: chìa khóa; breakfast: bữa sáng; check out: trả phòng\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "I have a reservation.", "vietnamese": "Tôi đã đặt phòng.", "position": 1}, {"english": "My name is Mikey.", "vietnamese": "Tên tôi là Mikey.", "position": 2}, {"english": "I would like a room for two nights.", "vietnamese": "Tôi muốn đặt một phòng trong hai đêm.", "position": 3}, {"english": "Is breakfast included?", "vietnamese": "Giá phòng đã bao gồm bữa sáng chưa?", "position": 4}, {"english": "What time is breakfast?", "vietnamese": "Bữa sáng bắt đầu lúc mấy giờ?", "position": 5}, {"english": "Can I have the room key, please?", "vietnamese": "Cho tôi xin chìa khóa phòng được không?", "position": 6}, {"english": "Is there Wi-Fi in the room?", "vietnamese": "Trong phòng có Wi-Fi không?", "position": 7}, {"english": "What is the Wi-Fi password?", "vietnamese": "Mật khẩu Wi-Fi là gì?", "position": 8}, {"english": "The air conditioner is not working.", "vietnamese": "Máy điều hòa không hoạt động.", "position": 9}, {"english": "I would like to check out.", "vietnamese": "Tôi muốn trả phòng.", "position": 10}]},
{"key": "a1-topic-22", "number": 22, "title": "Lesson 22: Asking for Help", "title_vi": "Nhờ giúp đỡ", "description": "Bài 22: Nhờ giúp đỡ. Luyện 10 mẫu câu giao tiếp Anh–Việt trong tình huống hằng ngày.", "objectives": "Hiểu và nói được 10 mẫu câu về nhờ giúp đỡ; luyện nghe, nhắc lại và thay từ để nói về bản thân.", "grammar": "Dùng Can you help me? và I need…; dùng please để yêu cầu lịch sự.", "vocabulary_notes": "help: giúp đỡ; lost: lạc đường; phone: điện thoại; understand: hiểu; emergency: tình huống khẩn cấp", "content": "Asking for Help – Nhờ giúp đỡ\n\nMục tiêu: Luyện giao tiếp cơ bản theo chủ đề.\n\nNgữ pháp: Dùng Can you help me? và I need…; dùng please để yêu cầu lịch sự.\n\nTừ vựng: help: giúp đỡ; lost: lạc đường; phone: điện thoại; understand: hiểu; emergency: tình huống khẩn cấp\n\nCách học:\n1. Nghe và nhắc lại mỗi câu ba lần.\n2. Tắt bản dịch và nói lại nghĩa của câu.\n3. Thay tên, thời gian hoặc địa điểm để tạo câu của bạn.\n4. Ghép các câu thành một đoạn hội thoại ngắn.", "sentences": [{"english": "Excuse me, can you help me?", "vietnamese": "Xin lỗi, bạn có thể giúp tôi không?", "position": 1}, {"english": "I am lost.", "vietnamese": "Tôi bị lạc đường.", "position": 2}, {"english": "I cannot find my phone.", "vietnamese": "Tôi không tìm thấy điện thoại.", "position": 3}, {"english": "Can I use your phone?", "vietnamese": "Tôi có thể dùng điện thoại của bạn không?", "position": 4}, {"english": "Please call my friend.", "vietnamese": "Vui lòng gọi bạn tôi.", "position": 5}, {"english": "I do not speak English very well.", "vietnamese": "Tôi nói tiếng Anh chưa tốt lắm.", "position": 6}, {"english": "Can you write it down, please?", "vietnamese": "Bạn có thể viết điều đó ra không?", "position": 7}, {"english": "Please show me what to do.", "vietnamese": "Vui lòng chỉ cho tôi phải làm gì.", "position": 8}, {"english": "It is an emergency.", "vietnamese": "Đây là tình huống khẩn cấp.", "position": 9}, {"english": "Thank you for helping me.", "vietnamese": "Cảm ơn bạn đã giúp tôi.", "position": 10}]}
]
$topic_data$::jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext(pack_id));
  IF NOT EXISTS (
    SELECT 1 FROM public.courses
    WHERE id = 1 AND regexp_replace(lower(title), '[^a-z0-9]', '', 'g') = 'englishwithmikeybasiccommunicationa1'
  ) THEN
    RAISE EXCEPTION 'Course 1 does not match Basic Communication A1. No changes made.';
  END IF;

  -- Check required lesson fields without altering the schema.
  FOREACH optional_column IN ARRAY ARRAY['content', 'objectives', 'status', 'order_index'] LOOP
    IF NOT EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'lessons' AND column_name = optional_column
    ) THEN
      RAISE EXCEPTION 'Missing lessons.% column. No changes made.', optional_column;
    END IF;
  END LOOP;

  -- Match either ordering convention and any available explanatory fields.
  FOREACH optional_column IN ARRAY ARRAY['sentence_order', 'order_index'] LOOP
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'sentences' AND column_name = optional_column
    ) THEN
      sentence_columns := sentence_columns || ', ' || quote_ident(optional_column);
      sentence_values := sentence_values || ', $4';
    END IF;
  END LOOP;
  IF sentence_columns = '' THEN
    RAISE EXCEPTION 'No supported sentence ordering column. No changes made.';
  END IF;
  FOREACH optional_column IN ARRAY ARRAY['vocabulary_notes', 'grammar_explanation', 'context_of_use'] LOOP
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'sentences' AND column_name = optional_column
    ) THEN
      sentence_columns := sentence_columns || ', ' || quote_ident(optional_column);
      sentence_values := sentence_values || CASE optional_column
        WHEN 'vocabulary_notes' THEN ', $5'
        WHEN 'grammar_explanation' THEN ', $6'
        ELSE ', $7' END;
    END IF;
  END LOOP;

  FOR lesson_record IN SELECT value FROM jsonb_array_elements(lesson_data) LOOP
    SELECT count(*) INTO previous_count FROM public.lessons
    WHERE course_id = 1 AND title = lesson_record->>'title';
    IF previous_count > 1 THEN
      RAISE EXCEPTION 'Duplicate lesson title: %. No changes made.', lesson_record->>'title';
    END IF;
    IF previous_count = 1 THEN
      SELECT description INTO previous_description FROM public.lessons
      WHERE course_id = 1 AND title = lesson_record->>'title';
      IF strpos(coalesce(previous_description, ''), pack_id) = 0 THEN
        RAISE EXCEPTION 'Existing unrelated lesson has title %. No changes made.', lesson_record->>'title';
      END IF;
      -- Never overwrite edits, publish status or saved student progress on rerun.
      skipped := skipped + 1;
      CONTINUE;
    END IF;

    INSERT INTO public.lessons (course_id, title, description, content, objectives, order_index, status)
    VALUES (
      1, lesson_record->>'title',
      (lesson_record->>'description') || E'\n\n/*--EWM_META:' ||
        jsonb_build_object('pack_id', pack_id, 'lesson_key', lesson_record->>'key')::text || ':EWM_META--*/',
      lesson_record->>'content', lesson_record->>'objectives',
      (lesson_record->>'number')::integer, 'Draft'
    ) RETURNING id INTO imported_lesson_id;

    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'public' AND table_name = 'lessons' AND column_name = 'lesson_order'
    ) THEN
      EXECUTE 'UPDATE public.lessons SET lesson_order = $1 WHERE id = $2'
      USING (lesson_record->>'number')::integer, imported_lesson_id;
    END IF;

    FOR sentence_record IN SELECT value FROM jsonb_array_elements(lesson_record->'sentences') LOOP
      EXECUTE 'INSERT INTO public.sentences (lesson_id, english, vietnamese' || sentence_columns ||
        ') VALUES ($1, $2, $3' || sentence_values || ')'
      USING imported_lesson_id, sentence_record->>'english', sentence_record->>'vietnamese',
        (sentence_record->>'position')::integer, lesson_record->>'vocabulary_notes',
        lesson_record->>'grammar', lesson_record->>'title_vi';
    END LOOP;
    added := added + 1;
  END LOOP;
  RAISE NOTICE 'Added % lessons (% sentences); skipped % previously imported lessons.', added, added * 10, skipped;
END;
$import$;
DO $upgrade$
DECLARE
  lesson_data jsonb := $upgrade_data$
[
{"title": "Lesson 3: My Family", "sentences": [{"english": "This is my family.", "vietnamese": "Đây là gia đình tôi.", "position": 1, "ipa": "/ðɪs ɪz maɪ fˈamɪli/"}, {"english": "This is my mother.", "vietnamese": "Đây là mẹ tôi.", "position": 2, "ipa": "/ðɪs ɪz maɪ mˈʌðə/"}, {"english": "This is my father.", "vietnamese": "Đây là bố tôi.", "position": 3, "ipa": "/ðɪs ɪz maɪ fˈɑːðə/"}, {"english": "I have one sister.", "vietnamese": "Tôi có một chị gái.", "position": 4, "ipa": "/aɪ hav wˈɒn sˈɪstə/"}, {"english": "I have two brothers.", "vietnamese": "Tôi có hai anh trai.", "position": 5, "ipa": "/aɪ hav tˈuː bɹˈʌðəz/"}, {"english": "My mother is a teacher.", "vietnamese": "Mẹ tôi là giáo viên.", "position": 6, "ipa": "/maɪ mˈʌðəɹ ɪz ɐ tˈiːtʃə/"}, {"english": "My father works in a shop.", "vietnamese": "Bố tôi làm việc ở một cửa hàng.", "position": 7, "ipa": "/maɪ fˈɑːðə wˈɜːks ɪn ɐ ʃˈɒp/"}, {"english": "We live in Hanoi.", "vietnamese": "Chúng tôi sống ở Hà Nội.", "position": 8, "ipa": "/wiː lˈɪv ɪn hanˈɔɪ/"}, {"english": "Do you have any brothers or sisters?", "vietnamese": "Bạn có anh chị em không?", "position": 9, "ipa": "/dˈuː juː hav ˌɛni bɹˈʌðəz ɔː sˈɪstəz/"}, {"english": "I love my family.", "vietnamese": "Tôi yêu gia đình mình.", "position": 10, "ipa": "/aɪ lˈʌv maɪ fˈamɪli/"}, {"english": "My family is small.", "vietnamese": "Gia đình tôi có ít người.", "position": 11, "ipa": "/maɪ fˈamɪli ɪz smˈɔːl/"}, {"english": "There are four people in my family.", "vietnamese": "Gia đình tôi có bốn người.", "position": 12, "ipa": "/ðeəɹˌɑː fˈɔː pˈiːpəl ɪn maɪ fˈamɪli/"}, {"english": "What is your mother's name?", "vietnamese": "Mẹ bạn tên là gì?", "position": 13, "ipa": "/wˌɒt ɪz jɔː mˈʌðəz nˈeɪm/"}, {"english": "Her name is Lan.", "vietnamese": "Bà ấy tên là Lan.", "position": 14, "ipa": "/hɜː nˈeɪm ɪz lˈan/"}, {"english": "How old is your father?", "vietnamese": "Bố bạn bao nhiêu tuổi?", "position": 15, "ipa": "/hˌaʊ ˈəʊld ɪz jɔː fˈɑːðə/"}, {"english": "He is fifty years old.", "vietnamese": "Ông ấy năm mươi tuổi.", "position": 16, "ipa": "/hiː ɪz fˈɪfti jˈiəz ˈəʊld/"}, {"english": "My sister lives near me.", "vietnamese": "Chị gái tôi sống gần tôi.", "position": 17, "ipa": "/maɪ sˈɪstə lˈaɪvz nˈiə mˌiː/"}, {"english": "My brother is a student.", "vietnamese": "Em trai tôi là học sinh.", "position": 18, "ipa": "/maɪ bɹˈʌðəɹ ɪz ɐ stjˈuːdənt/"}, {"english": "My parents live in Hue.", "vietnamese": "Bố mẹ tôi sống ở Huế.", "position": 19, "ipa": "/maɪ pˈeəɹənts lˈɪv ɪn hjˈuː/"}, {"english": "I visit my grandparents on Sundays.", "vietnamese": "Tôi đến thăm ông bà vào các ngày Chủ nhật.", "position": 20, "ipa": "/aɪ vˈɪzɪt maɪ ɡɹˈandpeəɹənts ˌɒn sˈʌndeɪz/"}, {"english": "My grandmother likes cooking.", "vietnamese": "Bà tôi thích nấu ăn.", "position": 21, "ipa": "/maɪ ɡɹˈandmʌðə lˈaɪks kˈʊkɪŋ/"}, {"english": "My grandfather likes reading.", "vietnamese": "Ông tôi thích đọc sách.", "position": 22, "ipa": "/maɪ ɡɹˈandfɑːðə lˈaɪks ɹˈiːdɪŋ/"}, {"english": "We eat dinner together.", "vietnamese": "Chúng tôi ăn tối cùng nhau.", "position": 23, "ipa": "/wiː ˈiːt dˈɪnə təɡˈɛðə/"}, {"english": "We talk after dinner.", "vietnamese": "Chúng tôi nói chuyện sau bữa tối.", "position": 24, "ipa": "/wiː tˈɔːk ˈaftə dˈɪnə/"}, {"english": "Who is that boy?", "vietnamese": "Cậu bé kia là ai?", "position": 25, "ipa": "/hˌuː ɪz ðat bˈɔɪ/"}, {"english": "He is my cousin.", "vietnamese": "Cậu ấy là em họ tôi.", "position": 26, "ipa": "/hiː ɪz maɪ kˈʌzən/"}, {"english": "Do you live with your parents?", "vietnamese": "Bạn có sống với bố mẹ không?", "position": 27, "ipa": "/dˈuː juː lˈɪv wɪð jɔː pˈeəɹənts/"}, {"english": "Yes, I live with my parents.", "vietnamese": "Có, tôi sống với bố mẹ.", "position": 28, "ipa": "/jˈɛs aɪ lˈɪv wɪð maɪ pˈeəɹənts/"}, {"english": "My aunt works in a hospital.", "vietnamese": "Dì tôi làm việc ở bệnh viện.", "position": 29, "ipa": "/maɪ ˈant wˈɜːks ɪn ɐ hˈɒspɪtəl/"}, {"english": "My uncle is a driver.", "vietnamese": "Chú tôi là tài xế.", "position": 30, "ipa": "/maɪ ˈʌŋkəl ɪz ɐ dɹˈaɪvə/"}], "grammar": "Dùng my/your và câu This is… để giới thiệu người thân.", "vocabulary_notes": "family: gia đình; mother: mẹ; father: bố; sister: chị/em gái; brother: anh/em trai", "title_vi": "Gia đình của tôi"},
{"title": "Lesson 4: My Home", "sentences": [{"english": "I live in a small house.", "vietnamese": "Tôi sống trong một ngôi nhà nhỏ.", "position": 1, "ipa": "/aɪ lˈɪv ɪn ɐ smˈɔːl hˈaʊs/"}, {"english": "There are two bedrooms.", "vietnamese": "Có hai phòng ngủ.", "position": 2, "ipa": "/ðeəɹˌɑː tˈuː bˈɛdɹuːmz/"}, {"english": "There is a kitchen.", "vietnamese": "Có một nhà bếp.", "position": 3, "ipa": "/ðeəɹ ɪz ɐ kˈɪtʃən/"}, {"english": "My room is upstairs.", "vietnamese": "Phòng tôi ở tầng trên.", "position": 4, "ipa": "/maɪ ɹˈuːm ɪz ʌpstˈeəz/"}, {"english": "The bathroom is next to my room.", "vietnamese": "Phòng tắm ở cạnh phòng tôi.", "position": 5, "ipa": "/ðə bˈaθɹuːm ɪz nˈɛkst tə maɪ ɹˈuːm/"}, {"english": "There is a table in the kitchen.", "vietnamese": "Có một chiếc bàn trong bếp.", "position": 6, "ipa": "/ðeəɹ ɪz ɐ tˈeɪbəl ɪnðə kˈɪtʃən/"}, {"english": "There are four chairs.", "vietnamese": "Có bốn chiếc ghế.", "position": 7, "ipa": "/ðeəɹˌɑː fˈɔː tʃˈeəz/"}, {"english": "My bag is on the chair.", "vietnamese": "Túi của tôi ở trên ghế.", "position": 8, "ipa": "/maɪ bˈaɡ ɪz ɒnðə tʃˈeə/"}, {"english": "The keys are under the table.", "vietnamese": "Chìa khóa ở dưới bàn.", "position": 9, "ipa": "/ðə kˈiːz ɑːɹ ˌʌndə ðə tˈeɪbəl/"}, {"english": "I like my home.", "vietnamese": "Tôi thích ngôi nhà của mình.", "position": 10, "ipa": "/aɪ lˈaɪk maɪ hˈəʊm/"}, {"english": "Where is your house?", "vietnamese": "Nhà bạn ở đâu?", "position": 11, "ipa": "/wˌeəɹ ɪz jɔː hˈaʊs/"}, {"english": "My house is near the park.", "vietnamese": "Nhà tôi ở gần công viên.", "position": 12, "ipa": "/maɪ hˈaʊs ɪz nˌiə ðə pˈɑːk/"}, {"english": "Do you live in a flat?", "vietnamese": "Bạn có sống trong căn hộ không?", "position": 13, "ipa": "/dˈuː juː lˈɪv ɪn ɐ flˈat/"}, {"english": "Yes, I live in a flat.", "vietnamese": "Có, tôi sống trong căn hộ.", "position": 14, "ipa": "/jˈɛs aɪ lˈɪv ɪn ɐ flˈat/"}, {"english": "The living room is large.", "vietnamese": "Phòng khách rộng.", "position": 15, "ipa": "/ðə lˈɪvɪŋ ɹˈuːm ɪz lˈɑːdʒ/"}, {"english": "My bedroom is small.", "vietnamese": "Phòng ngủ của tôi nhỏ.", "position": 16, "ipa": "/maɪ bˈɛdɹuːm ɪz smˈɔːl/"}, {"english": "There is a bed in my room.", "vietnamese": "Có một chiếc giường trong phòng tôi.", "position": 17, "ipa": "/ðeəɹ ɪz ɐ bˈɛd ɪn maɪ ɹˈuːm/"}, {"english": "There is a lamp on the desk.", "vietnamese": "Có một chiếc đèn trên bàn học.", "position": 18, "ipa": "/ðeəɹ ɪz ɐ lˈamp ɒnðə dˈɛsk/"}, {"english": "The window is open.", "vietnamese": "Cửa sổ đang mở.", "position": 19, "ipa": "/ðə wˈɪndəʊ ɪz ˈəʊpən/"}, {"english": "Please close the door.", "vietnamese": "Vui lòng đóng cửa lại.", "position": 20, "ipa": "/plˈiːz klˈəʊs ðə dˈɔː/"}, {"english": "Where are my shoes?", "vietnamese": "Giày của tôi ở đâu?", "position": 21, "ipa": "/wˌeəɹ ɑː maɪ ʃˈuːz/"}, {"english": "They are next to the door.", "vietnamese": "Chúng ở cạnh cửa.", "position": 22, "ipa": "/ðeɪ ɑː nˈɛkst tə ðə dˈɔː/"}, {"english": "The sofa is in the living room.", "vietnamese": "Ghế sofa ở trong phòng khách.", "position": 23, "ipa": "/ðə sˈəʊfəɹ ɪz ɪnðə lˈɪvɪŋ ɹˈuːm/"}, {"english": "There is a garden behind the house.", "vietnamese": "Có một khu vườn phía sau nhà.", "position": 24, "ipa": "/ðeəɹ ɪz ɐ ɡˈɑːdən bɪhˌaɪnd ðə hˈaʊs/"}, {"english": "We have a small balcony.", "vietnamese": "Chúng tôi có một ban công nhỏ.", "position": 25, "ipa": "/wiː hav ɐ smˈɔːl bˈalkəni/"}, {"english": "I clean my room on Saturdays.", "vietnamese": "Tôi dọn phòng vào các ngày thứ Bảy.", "position": 26, "ipa": "/aɪ klˈiːn maɪ ɹˈuːm ˌɒn sˈatədˌeɪz/"}, {"english": "The kitchen is downstairs.", "vietnamese": "Nhà bếp ở tầng dưới.", "position": 27, "ipa": "/ðə kˈɪtʃən ɪz dˈaʊnsteəz/"}, {"english": "My room is quiet.", "vietnamese": "Phòng tôi yên tĩnh.", "position": 28, "ipa": "/maɪ ɹˈuːm ɪz kwˈaɪət/"}, {"english": "There are some flowers on the table.", "vietnamese": "Có vài bông hoa trên bàn.", "position": 29, "ipa": "/ðeəɹˌɑː sˌʌm flˈaʊəz ɒnðə tˈeɪbəl/"}, {"english": "Please make yourself at home.", "vietnamese": "Bạn cứ tự nhiên như ở nhà nhé.", "position": 30, "ipa": "/plˈiːz mˌeɪk jɔːsˈɛlf at hˈəʊm/"}], "grammar": "Dùng there is + danh từ số ít và there are + danh từ số nhiều để mô tả nhà.", "vocabulary_notes": "home: nhà; bedroom: phòng ngủ; kitchen: nhà bếp; table: bàn; chair: ghế", "title_vi": "Ngôi nhà của tôi"},
{"title": "Lesson 5: Numbers and Age", "sentences": [{"english": "How old are you?", "vietnamese": "Bạn bao nhiêu tuổi?", "position": 1, "ipa": "/hˌaʊ ˈəʊld ɑː juː/"}, {"english": "I am twenty years old.", "vietnamese": "Tôi hai mươi tuổi.", "position": 2, "ipa": "/aɪɐm twˈɛnti jˈiəz ˈəʊld/"}, {"english": "My sister is eighteen.", "vietnamese": "Chị gái tôi mười tám tuổi.", "position": 3, "ipa": "/maɪ sˈɪstəɹ ɪz ˈeɪtiːn/"}, {"english": "There are ten students.", "vietnamese": "Có mười học sinh.", "position": 4, "ipa": "/ðeəɹˌɑː tˈɛn stjˈuːdənts/"}, {"english": "I have three books.", "vietnamese": "Tôi có ba quyển sách.", "position": 5, "ipa": "/aɪ hav θɹˈiː bˈʊks/"}, {"english": "Please count from one to ten.", "vietnamese": "Hãy đếm từ một đến mười.", "position": 6, "ipa": "/plˈiːz kˈaʊnt fɹɒm wˈɒn tə tˈɛn/"}, {"english": "What is your phone number?", "vietnamese": "Số điện thoại của bạn là gì?", "position": 7, "ipa": "/wˌɒt ɪz jɔː fˈəʊn nˈʌmbə/"}, {"english": "Please say the number again.", "vietnamese": "Vui lòng đọc lại số đó.", "position": 8, "ipa": "/plˈiːz sˈeɪ ðə nˈʌmbəɹ ɐɡˈɛn/"}, {"english": "Is this number correct?", "vietnamese": "Số này có đúng không?", "position": 9, "ipa": "/ɪz ðɪs nˈʌmbə kəɹˈɛkt/"}, {"english": "Yes, that is correct.", "vietnamese": "Vâng, đúng rồi.", "position": 10, "ipa": "/jˈɛs ðat ɪz kəɹˈɛkt/"}, {"english": "I am nineteen years old.", "vietnamese": "Tôi mười chín tuổi.", "position": 11, "ipa": "/aɪɐm nˈaɪntiːn jˈiəz ˈəʊld/"}, {"english": "My brother is twelve.", "vietnamese": "Em trai tôi mười hai tuổi.", "position": 12, "ipa": "/maɪ bɹˈʌðəɹ ɪz twˈɛlv/"}, {"english": "My father is forty-five.", "vietnamese": "Bố tôi bốn mươi lăm tuổi.", "position": 13, "ipa": "/maɪ fˈɑːðəɹ ɪz fˈɔːtifˈaɪv/"}, {"english": "My grandmother is seventy.", "vietnamese": "Bà tôi bảy mươi tuổi.", "position": 14, "ipa": "/maɪ ɡɹˈandmʌðəɹ ɪz sˈɛvənti/"}, {"english": "How many people are there?", "vietnamese": "Có bao nhiêu người?", "position": 15, "ipa": "/hˌaʊ mˈɛni pˈiːpəl ɑː ðˈeə/"}, {"english": "There are six people.", "vietnamese": "Có sáu người.", "position": 16, "ipa": "/ðeəɹˌɑː sˈɪks pˈiːpəl/"}, {"english": "How many chairs do we need?", "vietnamese": "Chúng ta cần bao nhiêu chiếc ghế?", "position": 17, "ipa": "/hˌaʊ mˈɛni tʃˈeəz dˈuː wiː nˈiːd/"}, {"english": "We need eight chairs.", "vietnamese": "Chúng ta cần tám chiếc ghế.", "position": 18, "ipa": "/wiː nˈiːd ˈeɪt tʃˈeəz/"}, {"english": "I have fifteen pencils.", "vietnamese": "Tôi có mười lăm chiếc bút chì.", "position": 19, "ipa": "/aɪ hav fˈɪftiːn pˈɛnsəlz/"}, {"english": "The room number is twenty-one.", "vietnamese": "Số phòng là hai mươi mốt.", "position": 20, "ipa": "/ðə ɹˈuːm nˈʌmbəɹ ɪz twˈɛntiwˌɒn/"}, {"english": "Please write your number here.", "vietnamese": "Vui lòng viết số của bạn ở đây.", "position": 21, "ipa": "/plˈiːz ɹˈaɪt jɔː nˈʌmbə hˈiə/"}, {"english": "Can you count backwards from ten?", "vietnamese": "Bạn có thể đếm ngược từ mười không?", "position": 22, "ipa": "/kan juː kˈaʊnt bˈakwədz fɹɒm tˈɛn/"}, {"english": "There are thirty days in April.", "vietnamese": "Tháng Tư có ba mươi ngày.", "position": 23, "ipa": "/ðeəɹˌɑː θˈɜːti dˈeɪz ɪn ˈeɪpɹəl/"}, {"english": "There are seven days in a week.", "vietnamese": "Một tuần có bảy ngày.", "position": 24, "ipa": "/ðeəɹˌɑː sˈɛvən dˈeɪz ɪn ɐ wˈiːk/"}, {"english": "One plus two is three.", "vietnamese": "Một cộng hai bằng ba.", "position": 25, "ipa": "/wˈɒn plˈʌs tˈuː ɪz θɹˈiː/"}, {"english": "Ten minus four is six.", "vietnamese": "Mười trừ bốn bằng sáu.", "position": 26, "ipa": "/tˈɛn mˈaɪnəs fˈɔːɹ ɪz sˈɪks/"}, {"english": "I need five more minutes.", "vietnamese": "Tôi cần thêm năm phút.", "position": 27, "ipa": "/aɪ nˈiːd fˈaɪv mˈɔː mˈɪnɪts/"}, {"english": "My birthday is in May.", "vietnamese": "Sinh nhật tôi vào tháng Năm.", "position": 28, "ipa": "/maɪ bˈɜːθdeɪ ɪz ɪn mˈeɪ/"}, {"english": "Today is my birthday.", "vietnamese": "Hôm nay là sinh nhật tôi.", "position": 29, "ipa": "/tədˈeɪ ɪz maɪ bˈɜːθdeɪ/"}, {"english": "Happy birthday to you!", "vietnamese": "Chúc mừng sinh nhật bạn!", "position": 30, "ipa": "/hˈapi bˈɜːθdeɪ tə juː/"}], "grammar": "Hỏi tuổi bằng How old are you? Trả lời bằng I am + số tuổi.", "vocabulary_notes": "number: số; age: tuổi; year: năm; old: có tuổi; phone number: số điện thoại", "title_vi": "Số đếm và tuổi"},
{"title": "Lesson 6: Time and Days", "sentences": [{"english": "What time is it?", "vietnamese": "Bây giờ là mấy giờ?", "position": 1, "ipa": "/wˌɒt tˈaɪm ɪz ɪt/"}, {"english": "It is nine o'clock.", "vietnamese": "Bây giờ là chín giờ.", "position": 2, "ipa": "/ɪt ɪz nˈaɪn əklˈɒk/"}, {"english": "It is half past seven.", "vietnamese": "Bây giờ là bảy giờ rưỡi.", "position": 3, "ipa": "/ɪt ɪz hˈɑːf pˈast sˈɛvən/"}, {"english": "What day is it today?", "vietnamese": "Hôm nay là thứ mấy?", "position": 4, "ipa": "/wˌɒt dˈeɪ ɪz ɪt tədˈeɪ/"}, {"english": "Today is Monday.", "vietnamese": "Hôm nay là thứ Hai.", "position": 5, "ipa": "/tədˈeɪ ɪz mˈʌndeɪ/"}, {"english": "Tomorrow is Tuesday.", "vietnamese": "Ngày mai là thứ Ba.", "position": 6, "ipa": "/təmˈɒɹəʊ ɪz tjˈuːzdeɪ/"}, {"english": "The class starts at eight.", "vietnamese": "Lớp học bắt đầu lúc tám giờ.", "position": 7, "ipa": "/ðə klˈas stˈɑːts at ˈeɪt/"}, {"english": "I study English on Fridays.", "vietnamese": "Tôi học tiếng Anh vào các ngày thứ Sáu.", "position": 8, "ipa": "/aɪ stˈʌdi ˈɪŋɡlɪʃ ˌɒn fɹˈaɪdeɪz/"}, {"english": "Are you free on Sunday?", "vietnamese": "Bạn có rảnh vào Chủ nhật không?", "position": 9, "ipa": "/ɑː juː fɹˈiː ˌɒn sˈʌndeɪ/"}, {"english": "See you on Saturday.", "vietnamese": "Hẹn gặp bạn vào thứ Bảy.", "position": 10, "ipa": "/sˈiː juː ˌɒn sˈatədˌeɪ/"}, {"english": "It is six in the morning.", "vietnamese": "Bây giờ là sáu giờ sáng.", "position": 11, "ipa": "/ɪt ɪz sˈɪks ɪnðə mˈɔːnɪŋ/"}, {"english": "It is ten at night.", "vietnamese": "Bây giờ là mười giờ tối.", "position": 12, "ipa": "/ɪt ɪz tˈɛn at nˈaɪt/"}, {"english": "It is a quarter past eight.", "vietnamese": "Bây giờ là tám giờ mười lăm.", "position": 13, "ipa": "/ɪt ɪz ɐ kwˈɔːtə pˈast ˈeɪt/"}, {"english": "It is a quarter to nine.", "vietnamese": "Bây giờ là tám giờ bốn mươi lăm.", "position": 14, "ipa": "/ɪt ɪz ɐ kwˈɔːtə tə nˈaɪn/"}, {"english": "What time do you start work?", "vietnamese": "Bạn bắt đầu làm việc lúc mấy giờ?", "position": 15, "ipa": "/wˌɒt tˈaɪm dˈuː juː stˈɑːt wˈɜːk/"}, {"english": "I start work at half past eight.", "vietnamese": "Tôi bắt đầu làm việc lúc tám giờ rưỡi.", "position": 16, "ipa": "/aɪ stˈɑːt wˈɜːk at hˈɑːf pˈast ˈeɪt/"}, {"english": "What time does the shop close?", "vietnamese": "Cửa hàng đóng cửa lúc mấy giờ?", "position": 17, "ipa": "/wˌɒt tˈaɪm dˈʌz ðə ʃˈɒp klˈəʊs/"}, {"english": "It closes at six.", "vietnamese": "Cửa hàng đóng cửa lúc sáu giờ.", "position": 18, "ipa": "/ɪt klˈəʊzɪz at sˈɪks/"}, {"english": "I am busy on Wednesday.", "vietnamese": "Tôi bận vào thứ Tư.", "position": 19, "ipa": "/aɪɐm bˈɪzi ˌɒn wˈɛnzdeɪ/"}, {"english": "Thursday is a good day for me.", "vietnamese": "Thứ Năm là ngày phù hợp với tôi.", "position": 20, "ipa": "/θˈɜːzdeɪ ɪz ɐ ɡˈʊd dˈeɪ fɔː mˌiː/"}, {"english": "The meeting is on Friday.", "vietnamese": "Cuộc họp diễn ra vào thứ Sáu.", "position": 21, "ipa": "/ðə mˈiːtɪŋ ɪz ˌɒn fɹˈaɪdeɪ/"}, {"english": "We have lunch at noon.", "vietnamese": "Chúng tôi ăn trưa vào buổi trưa.", "position": 22, "ipa": "/wiː hav lˈʌntʃ at nˈuːn/"}, {"english": "I study in the evening.", "vietnamese": "Tôi học vào buổi tối.", "position": 23, "ipa": "/aɪ stˈʌdi ɪnðɪ ˈiːvnɪŋ/"}, {"english": "Please arrive on time.", "vietnamese": "Vui lòng đến đúng giờ.", "position": 24, "ipa": "/plˈiːz ɐɹˈaɪv ˌɒn tˈaɪm/"}, {"english": "I am five minutes late.", "vietnamese": "Tôi đến muộn năm phút.", "position": 25, "ipa": "/aɪɐm fˈaɪv mˈɪnɪts lˈeɪt/"}, {"english": "What is the date today?", "vietnamese": "Hôm nay là ngày bao nhiêu?", "position": 26, "ipa": "/wˌɒt ɪz ðə dˈeɪt tədˈeɪ/"}, {"english": "Today is the first of June.", "vietnamese": "Hôm nay là ngày một tháng Sáu.", "position": 27, "ipa": "/tədˈeɪ ɪz ðə fˈɜːst ɒv dʒˈuːn/"}, {"english": "My appointment is at three.", "vietnamese": "Cuộc hẹn của tôi lúc ba giờ.", "position": 28, "ipa": "/maɪ ɐpˈɔɪntmənt ɪz at θɹˈiː/"}, {"english": "Can we meet after lunch?", "vietnamese": "Chúng ta có thể gặp nhau sau bữa trưa không?", "position": 29, "ipa": "/kan wiː mˈiːt ˈaftə lˈʌntʃ/"}, {"english": "Let us meet before six.", "vietnamese": "Chúng ta hãy gặp nhau trước sáu giờ.", "position": 30, "ipa": "/lˈɛt ˌʌs mˈiːt bɪfˌɔː sˈɪks/"}], "grammar": "Dùng at trước giờ, on trước ngày trong tuần; hỏi giờ bằng What time is it?", "vocabulary_notes": "time: thời gian; Monday: thứ Hai; Friday: thứ Sáu; today: hôm nay; tomorrow: ngày mai", "title_vi": "Giờ và các ngày trong tuần"},
{"title": "Lesson 7: Food and Drinks", "sentences": [{"english": "I like rice and chicken.", "vietnamese": "Tôi thích cơm và thịt gà.", "position": 1, "ipa": "/aɪ lˈaɪk ɹˈaɪs and tʃˈɪkɪn/"}, {"english": "I eat vegetables every day.", "vietnamese": "Tôi ăn rau mỗi ngày.", "position": 2, "ipa": "/aɪ ˈiːt vˈɛdʒɪtəbəlz ˈɛvɹɪ dˈeɪ/"}, {"english": "I drink water with my lunch.", "vietnamese": "Tôi uống nước trong bữa trưa.", "position": 3, "ipa": "/aɪ dɹˈɪŋk wˈɔːtə wɪð maɪ lˈʌntʃ/"}, {"english": "Do you like coffee?", "vietnamese": "Bạn có thích cà phê không?", "position": 4, "ipa": "/dˈuː juː lˈaɪk kˈɒfi/"}, {"english": "I prefer tea.", "vietnamese": "Tôi thích trà hơn.", "position": 5, "ipa": "/aɪ pɹɪfˈɜː tˈiː/"}, {"english": "I do not like milk.", "vietnamese": "Tôi không thích sữa.", "position": 6, "ipa": "/aɪ duːnˌɒt lˈaɪk mˈɪlk/"}, {"english": "Would you like some juice?", "vietnamese": "Bạn có muốn uống nước ép không?", "position": 7, "ipa": "/wʊd juː lˈaɪk sˌʌm dʒˈuːs/"}, {"english": "Yes, please.", "vietnamese": "Vâng, cho tôi xin.", "position": 8, "ipa": "/jˈɛs plˈiːz/"}, {"english": "No, thank you.", "vietnamese": "Không, cảm ơn bạn.", "position": 9, "ipa": "/nˈəʊ θˈaŋk juː/"}, {"english": "This soup is very good.", "vietnamese": "Món súp này rất ngon.", "position": 10, "ipa": "/ðɪs sˈuːp ɪz vˈɛɹi ɡˈʊd/"}, {"english": "What is your favourite food?", "vietnamese": "Món ăn yêu thích của bạn là gì?", "position": 11, "ipa": "/wˌɒt ɪz jɔː fˈeɪvɹɪt fˈuːd/"}, {"english": "My favourite food is noodles.", "vietnamese": "Món ăn yêu thích của tôi là mì.", "position": 12, "ipa": "/maɪ fˈeɪvɹɪt fˈuːd ɪz nˈuːdəlz/"}, {"english": "I like fish.", "vietnamese": "Tôi thích cá.", "position": 13, "ipa": "/aɪ lˈaɪk fˈɪʃ/"}, {"english": "I do not eat meat.", "vietnamese": "Tôi không ăn thịt.", "position": 14, "ipa": "/aɪ duːnˌɒt ˈiːt mˈiːt/"}, {"english": "Do you eat eggs for breakfast?", "vietnamese": "Bạn có ăn trứng vào bữa sáng không?", "position": 15, "ipa": "/dˈuː juː ˈiːt ˈɛɡz fɔː bɹˈɛkfəst/"}, {"english": "I have bread and fruit.", "vietnamese": "Tôi ăn bánh mì và trái cây.", "position": 16, "ipa": "/aɪ hav bɹˈɛd and fɹˈuːt/"}, {"english": "Would you like an apple?", "vietnamese": "Bạn có muốn ăn một quả táo không?", "position": 17, "ipa": "/wʊd juː lˈaɪk ɐn ˈapəl/"}, {"english": "I would like a banana.", "vietnamese": "Tôi muốn ăn một quả chuối.", "position": 18, "ipa": "/aɪ wʊd lˈaɪk ɐ bɐnˈɑːnə/"}, {"english": "There is some cheese in the fridge.", "vietnamese": "Có một ít phô mai trong tủ lạnh.", "position": 19, "ipa": "/ðeəɹ ɪz sˌʌm tʃˈiːz ɪnðə fɹˈɪdʒ/"}, {"english": "We need some fresh vegetables.", "vietnamese": "Chúng ta cần một ít rau tươi.", "position": 20, "ipa": "/wiː nˈiːd sˌʌm fɹˈɛʃ vˈɛdʒɪtəbəlz/"}, {"english": "I am hungry.", "vietnamese": "Tôi đói.", "position": 21, "ipa": "/aɪɐm hˈʌŋɡɹi/"}, {"english": "I am thirsty.", "vietnamese": "Tôi khát.", "position": 22, "ipa": "/aɪɐm θˈɜːsti/"}, {"english": "This tea is hot.", "vietnamese": "Trà này nóng.", "position": 23, "ipa": "/ðɪs tˈiː ɪz hˈɒt/"}, {"english": "The water is cold.", "vietnamese": "Nước lạnh.", "position": 24, "ipa": "/ðə wˈɔːtəɹ ɪz kˈəʊld/"}, {"english": "Please pass the salt.", "vietnamese": "Vui lòng đưa giúp tôi lọ muối.", "position": 25, "ipa": "/plˈiːz pˈas ðə sˈɒlt/"}, {"english": "Do you want some sugar?", "vietnamese": "Bạn có muốn thêm đường không?", "position": 26, "ipa": "/dˈuː juː wˈɒnt sˌʌm ʃˈʊɡə/"}, {"english": "I take my coffee without sugar.", "vietnamese": "Tôi uống cà phê không đường.", "position": 27, "ipa": "/aɪ tˈeɪk maɪ kˈɒfi wɪðˌaʊt ʃˈʊɡə/"}, {"english": "I am allergic to peanuts.", "vietnamese": "Tôi bị dị ứng với đậu phộng.", "position": 28, "ipa": "/aɪɐm ɐlˈɜːdʒɪk tə pˈiːnʌts/"}, {"english": "Does this contain milk?", "vietnamese": "Món này có chứa sữa không?", "position": 29, "ipa": "/dˈʌz ðɪs kəntˈeɪn mˈɪlk/"}, {"english": "I am full, thank you.", "vietnamese": "Tôi no rồi, cảm ơn bạn.", "position": 30, "ipa": "/aɪɐm fˈʊl θˈaŋk juː/"}], "grammar": "Dùng I like/I do not like để nói sở thích; dùng some với lượng không xác định.", "vocabulary_notes": "food: đồ ăn; water: nước; rice: cơm; chicken: thịt gà; vegetables: rau", "title_vi": "Đồ ăn và thức uống"},
{"title": "Lesson 8: At a Restaurant", "sentences": [{"english": "A table for two, please.", "vietnamese": "Cho tôi một bàn hai người.", "position": 1, "ipa": "/ɐ tˈeɪbəl fɔː tˈuː plˈiːz/"}, {"english": "Can I see the menu, please?", "vietnamese": "Cho tôi xem thực đơn được không?", "position": 2, "ipa": "/kan aɪ sˈiː ðə mˈɛnjuː plˈiːz/"}, {"english": "I would like some chicken.", "vietnamese": "Tôi muốn gọi một phần thịt gà.", "position": 3, "ipa": "/aɪ wʊd lˈaɪk sˌʌm tʃˈɪkɪn/"}, {"english": "Can I have some water, please?", "vietnamese": "Cho tôi xin ít nước được không?", "position": 4, "ipa": "/kan aɪ hav sˌʌm wˈɔːtə plˈiːz/"}, {"english": "What would you like to drink?", "vietnamese": "Bạn muốn uống gì?", "position": 5, "ipa": "/wˌɒt wʊd juː lˈaɪk tə dɹˈɪŋk/"}, {"english": "I would like a cup of tea.", "vietnamese": "Tôi muốn một tách trà.", "position": 6, "ipa": "/aɪ wʊd lˈaɪk ɐ kˈʌp ɒv tˈiː/"}, {"english": "Is this dish spicy?", "vietnamese": "Món này có cay không?", "position": 7, "ipa": "/ɪz ðɪs dˈɪʃ spˈaɪsi/"}, {"english": "Please do not add any chilli.", "vietnamese": "Vui lòng đừng cho ớt.", "position": 8, "ipa": "/plˈiːz duːnˌɒt ˈad ˌɛni tʃˈɪli/"}, {"english": "The food is delicious.", "vietnamese": "Đồ ăn rất ngon.", "position": 9, "ipa": "/ðə fˈuːd ɪz dɪlˈɪʃəs/"}, {"english": "Can I have the bill, please?", "vietnamese": "Cho tôi xin hóa đơn được không?", "position": 10, "ipa": "/kan aɪ hav ðə bˈɪl plˈiːz/"}, {"english": "Do you have a reservation?", "vietnamese": "Bạn đã đặt bàn chưa?", "position": 11, "ipa": "/dˈuː juː hav ɐ ɹˌɛzəvˈeɪʃən/"}, {"english": "Yes, I have a reservation for seven.", "vietnamese": "Vâng, tôi đã đặt bàn lúc bảy giờ.", "position": 12, "ipa": "/jˈɛs aɪ hav ɐ ɹˌɛzəvˈeɪʃən fɔː sˈɛvən/"}, {"english": "Can we sit by the window?", "vietnamese": "Chúng tôi có thể ngồi cạnh cửa sổ không?", "position": 13, "ipa": "/kan wiː sˈɪt baɪ ðə wˈɪndəʊ/"}, {"english": "Are you ready to order?", "vietnamese": "Bạn đã sẵn sàng gọi món chưa?", "position": 14, "ipa": "/ɑː juː ɹˈɛdi tʊ ˈɔːdə/"}, {"english": "We need a little more time.", "vietnamese": "Chúng tôi cần thêm một chút thời gian.", "position": 15, "ipa": "/wiː nˈiːd ɐ lˈɪtəl mˈɔː tˈaɪm/"}, {"english": "What do you recommend?", "vietnamese": "Bạn gợi ý món gì?", "position": 16, "ipa": "/wˌɒt dˈuː juː ɹˌɛkəmˈɛnd/"}, {"english": "I recommend the fish.", "vietnamese": "Tôi gợi ý món cá.", "position": 17, "ipa": "/aɪ ɹˌɛkəmˈɛnd ðə fˈɪʃ/"}, {"english": "I would like the vegetable soup.", "vietnamese": "Tôi muốn gọi món súp rau.", "position": 18, "ipa": "/aɪ wʊd lˈaɪk ðə vˈɛdʒɪtəbəl sˈuːp/"}, {"english": "Can I have rice with that?", "vietnamese": "Cho tôi ăn kèm cơm được không?", "position": 19, "ipa": "/kan aɪ hav ɹˈaɪs wɪð ðˈat/"}, {"english": "Just a small portion, please.", "vietnamese": "Cho tôi một phần nhỏ thôi.", "position": 20, "ipa": "/dʒˈʌst ɐ smˈɔːl pˈɔːʃən plˈiːz/"}, {"english": "Can we have two glasses of water?", "vietnamese": "Cho chúng tôi hai cốc nước được không?", "position": 21, "ipa": "/kan wiː hav tˈuː ɡlˈasɪz ɒv wˈɔːtə/"}, {"english": "Is there a vegetarian option?", "vietnamese": "Ở đây có món chay không?", "position": 22, "ipa": "/ɪz ðeəɹ ɐ vˌɛdʒɪtˈeəɹiən ˈɒpʃən/"}, {"english": "I cannot eat peanuts.", "vietnamese": "Tôi không thể ăn đậu phộng.", "position": 23, "ipa": "/aɪ kˈanɒt ˈiːt pˈiːnʌts/"}, {"english": "How long will it take?", "vietnamese": "Món ăn sẽ mất bao lâu?", "position": 24, "ipa": "/hˌaʊ lˈɒŋ wɪl ɪt tˈeɪk/"}, {"english": "About fifteen minutes.", "vietnamese": "Khoảng mười lăm phút.", "position": 25, "ipa": "/ɐbˌaʊt fˈɪftiːn mˈɪnɪts/"}, {"english": "Excuse me, this is not my order.", "vietnamese": "Xin lỗi, đây không phải món tôi đã gọi.", "position": 26, "ipa": "/ɛkskjˈuːs mˌiː ðɪs ɪz nˌɒt maɪ ˈɔːdə/"}, {"english": "Can we have some more napkins?", "vietnamese": "Cho chúng tôi thêm khăn giấy được không?", "position": 27, "ipa": "/kan wiː hav sˌʌm mˈɔː nˈapkɪnz/"}, {"english": "Everything is very nice.", "vietnamese": "Mọi thứ đều rất ngon.", "position": 28, "ipa": "/ˈɛvɹɪθˌɪŋ ɪz vˈɛɹi nˈaɪs/"}, {"english": "Can we pay separately?", "vietnamese": "Chúng tôi có thể thanh toán riêng không?", "position": 29, "ipa": "/kan wiː pˈeɪ sˈɛpɹətli/"}, {"english": "Keep the change, please.", "vietnamese": "Bạn cứ giữ tiền thừa nhé.", "position": 30, "ipa": "/kˈiːp ðə tʃˈeɪndʒ plˈiːz/"}], "grammar": "Dùng I would like… để gọi món lịch sự; Can I have…? để yêu cầu.", "vocabulary_notes": "menu: thực đơn; order: gọi món; soup: súp; bill: hóa đơn; delicious: ngon", "title_vi": "Tại nhà hàng"},
{"title": "Lesson 9: Shopping and Prices", "sentences": [{"english": "How much is this bag?", "vietnamese": "Chiếc túi này giá bao nhiêu?", "position": 1, "ipa": "/hˌaʊ mˈʌtʃ ɪz ðɪs bˈaɡ/"}, {"english": "It is two hundred thousand dong.", "vietnamese": "Giá của nó là hai trăm nghìn đồng.", "position": 2, "ipa": "/ɪt ɪz tˈuː hˈʌndɹɪd θˈaʊzənd dˈɒŋ/"}, {"english": "That is too expensive.", "vietnamese": "Giá đó đắt quá.", "position": 3, "ipa": "/ðat ɪz tˈuː ɛkspˈɛnsɪv/"}, {"english": "Do you have a cheaper one?", "vietnamese": "Bạn có loại rẻ hơn không?", "position": 4, "ipa": "/dˈuː juː hav ɐ tʃˈiːpə wˌɒn/"}, {"english": "I am just looking, thank you.", "vietnamese": "Tôi chỉ xem thôi, cảm ơn bạn.", "position": 5, "ipa": "/aɪɐm dʒˈʌst lˈʊkɪŋ θˈaŋk juː/"}, {"english": "I would like to buy this.", "vietnamese": "Tôi muốn mua món này.", "position": 6, "ipa": "/aɪ wʊd lˈaɪk tə bˈaɪ ðˈɪs/"}, {"english": "Can I pay by card?", "vietnamese": "Tôi có thể thanh toán bằng thẻ không?", "position": 7, "ipa": "/kan aɪ pˈeɪ baɪ kˈɑːd/"}, {"english": "I will pay in cash.", "vietnamese": "Tôi sẽ trả bằng tiền mặt.", "position": 8, "ipa": "/aɪ wɪl pˈeɪ ɪn kˈaʃ/"}, {"english": "Can I have a receipt, please?", "vietnamese": "Cho tôi xin biên lai được không?", "position": 9, "ipa": "/kan aɪ hav ɐ ɹɪsˈiːt plˈiːz/"}, {"english": "Thank you for your help.", "vietnamese": "Cảm ơn bạn đã giúp đỡ.", "position": 10, "ipa": "/θˈaŋk juː fɔː jɔː hˈɛlp/"}, {"english": "Where can I buy a notebook?", "vietnamese": "Tôi có thể mua vở ở đâu?", "position": 11, "ipa": "/wˌeə kan aɪ bˈaɪ ɐ nˈəʊtbʊk/"}, {"english": "I am looking for a small bag.", "vietnamese": "Tôi đang tìm một chiếc túi nhỏ.", "position": 12, "ipa": "/aɪɐm lˈʊkɪŋ fəɹə smˈɔːl bˈaɡ/"}, {"english": "How much are these shoes?", "vietnamese": "Đôi giày này giá bao nhiêu?", "position": 13, "ipa": "/hˌaʊ mˈʌtʃ ɑː ðiːz ʃˈuːz/"}, {"english": "They are five hundred thousand dong.", "vietnamese": "Đôi giày có giá năm trăm nghìn đồng.", "position": 14, "ipa": "/ðeɪ ɑː fˈaɪv hˈʌndɹɪd θˈaʊzənd dˈɒŋ/"}, {"english": "Is this on sale?", "vietnamese": "Món này có đang giảm giá không?", "position": 15, "ipa": "/ɪz ðɪs ˌɒn sˈeɪl/"}, {"english": "Do you have this in blue?", "vietnamese": "Bạn có món này màu xanh dương không?", "position": 16, "ipa": "/dˈuː juː hav ðɪs ɪn blˈuː/"}, {"english": "Can I see another one?", "vietnamese": "Tôi có thể xem chiếc khác không?", "position": 17, "ipa": "/kan aɪ sˈiː ɐnˈʌðə wˌɒn/"}, {"english": "This one is very nice.", "vietnamese": "Chiếc này rất đẹp.", "position": 18, "ipa": "/ðˈɪswˌɒn ɪz vˈɛɹi nˈaɪs/"}, {"english": "I will take it.", "vietnamese": "Tôi sẽ lấy món này.", "position": 19, "ipa": "/aɪ wɪl tˈeɪk ɪt/"}, {"english": "I need two of these.", "vietnamese": "Tôi cần hai món này.", "position": 20, "ipa": "/aɪ nˈiːd tˈuː ɒv ðˈiːz/"}, {"english": "Do you sell batteries?", "vietnamese": "Bạn có bán pin không?", "position": 21, "ipa": "/dˈuː juː sˈɛl bˈatəɹiz/"}, {"english": "Where is the supermarket?", "vietnamese": "Siêu thị ở đâu?", "position": 22, "ipa": "/wˌeəɹ ɪz ðə sˈuːpəmˌɑːkɪt/"}, {"english": "What time do you open?", "vietnamese": "Cửa hàng mở cửa lúc mấy giờ?", "position": 23, "ipa": "/wˌɒt tˈaɪm dˈuː juː ˈəʊpən/"}, {"english": "We open at nine.", "vietnamese": "Chúng tôi mở cửa lúc chín giờ.", "position": 24, "ipa": "/wiː ˈəʊpən at nˈaɪn/"}, {"english": "Can I have a bag, please?", "vietnamese": "Cho tôi xin một chiếc túi được không?", "position": 25, "ipa": "/kan aɪ hav ɐ bˈaɡ plˈiːz/"}, {"english": "I have my own bag.", "vietnamese": "Tôi có túi riêng rồi.", "position": 26, "ipa": "/aɪ hav maɪ ˈəʊn bˈaɡ/"}, {"english": "Here is your change.", "vietnamese": "Đây là tiền thừa của bạn.", "position": 27, "ipa": "/hˈiəɹ ɪz jɔː tʃˈeɪndʒ/"}, {"english": "Can I return this?", "vietnamese": "Tôi có thể trả lại món này không?", "position": 28, "ipa": "/kan aɪ ɹɪtˈɜːn ðˈɪs/"}, {"english": "I have the receipt.", "vietnamese": "Tôi có biên lai.", "position": 29, "ipa": "/aɪ hav ðə ɹɪsˈiːt/"}, {"english": "The shop is closed today.", "vietnamese": "Hôm nay cửa hàng đóng cửa.", "position": 30, "ipa": "/ðə ʃˈɒp ɪz klˈəʊzd tədˈeɪ/"}], "grammar": "Hỏi giá bằng How much is…? Dùng this cho vật ở gần, that cho vật ở xa.", "vocabulary_notes": "price: giá; buy: mua; cash: tiền mặt; card: thẻ; expensive: đắt", "title_vi": "Mua sắm và giá cả"},
{"title": "Lesson 10: Clothes and Colours", "sentences": [{"english": "I need a new shirt.", "vietnamese": "Tôi cần một chiếc áo sơ mi mới.", "position": 1, "ipa": "/aɪ nˈiːd ɐ njˈuː ʃˈɜːt/"}, {"english": "I like the blue one.", "vietnamese": "Tôi thích chiếc màu xanh dương.", "position": 2, "ipa": "/aɪ lˈaɪk ðə blˈuː wˌɒn/"}, {"english": "What colour do you like?", "vietnamese": "Bạn thích màu gì?", "position": 3, "ipa": "/wˌɒt kˈʌlə dˈuː juː lˈaɪk/"}, {"english": "I like red.", "vietnamese": "Tôi thích màu đỏ.", "position": 4, "ipa": "/aɪ lˈaɪk ɹˈɛd/"}, {"english": "What size do you need?", "vietnamese": "Bạn cần cỡ nào?", "position": 5, "ipa": "/wˌɒt sˈaɪz dˈuː juː nˈiːd/"}, {"english": "I need a medium.", "vietnamese": "Tôi cần cỡ vừa.", "position": 6, "ipa": "/aɪ nˈiːd ɐ mˈiːdiəm/"}, {"english": "Can I try this on?", "vietnamese": "Tôi có thể thử chiếc này không?", "position": 7, "ipa": "/kan aɪ tɹˈaɪ ðɪs ˈɒn/"}, {"english": "Where is the fitting room?", "vietnamese": "Phòng thử đồ ở đâu?", "position": 8, "ipa": "/wˌeəɹ ɪz ðə fˈɪtɪŋ ɹˈuːm/"}, {"english": "These shoes are too small.", "vietnamese": "Đôi giày này nhỏ quá.", "position": 9, "ipa": "/ðiːz ʃˈuːz ɑː tˈuː smˈɔːl/"}, {"english": "This jacket fits well.", "vietnamese": "Chiếc áo khoác này vừa vặn.", "position": 10, "ipa": "/ðɪs dʒˈakɪt fˈɪts wˈɛl/"}, {"english": "What are you wearing today?", "vietnamese": "Hôm nay bạn mặc gì?", "position": 11, "ipa": "/wˌɒt ɑː juː wˈeəɹɪŋ tədˈeɪ/"}, {"english": "I am wearing a white shirt.", "vietnamese": "Tôi đang mặc áo sơ mi trắng.", "position": 12, "ipa": "/aɪɐm wˈeəɹɪŋ ɐ wˈaɪt ʃˈɜːt/"}, {"english": "My trousers are black.", "vietnamese": "Quần dài của tôi màu đen.", "position": 13, "ipa": "/maɪ tɹˈaʊsəz ɑː blˈak/"}, {"english": "She is wearing a green dress.", "vietnamese": "Cô ấy đang mặc một chiếc váy xanh lá.", "position": 14, "ipa": "/ʃiː ɪz wˈeəɹɪŋ ɐ ɡɹˈiːn dɹˈɛs/"}, {"english": "These socks are yellow.", "vietnamese": "Đôi tất này màu vàng.", "position": 15, "ipa": "/ðiːz sˈɒks ɑː jˈɛləʊ/"}, {"english": "My favourite colour is purple.", "vietnamese": "Màu yêu thích của tôi là tím.", "position": 16, "ipa": "/maɪ fˈeɪvɹɪt kˈʌləɹ ɪz pˈɜːpəl/"}, {"english": "Do you have a larger size?", "vietnamese": "Bạn có cỡ lớn hơn không?", "position": 17, "ipa": "/dˈuː juː hav ɐ lˈɑːdʒə sˈaɪz/"}, {"english": "This is too big for me.", "vietnamese": "Chiếc này quá rộng với tôi.", "position": 18, "ipa": "/ðɪs ɪz tˈuː bˈɪɡ fɔː mˌiː/"}, {"english": "These trousers are too long.", "vietnamese": "Chiếc quần này dài quá.", "position": 19, "ipa": "/ðiːz tɹˈaʊsəz ɑː tˈuː lˈɒŋ/"}, {"english": "I need a pair of shoes.", "vietnamese": "Tôi cần một đôi giày.", "position": 20, "ipa": "/aɪ nˈiːd ɐ pˈeəɹ ɒv ʃˈuːz/"}, {"english": "Can I try a smaller size?", "vietnamese": "Tôi có thể thử cỡ nhỏ hơn không?", "position": 21, "ipa": "/kan aɪ tɹˈaɪ ɐ smˈɔːlə sˈaɪz/"}, {"english": "Where can I put my coat?", "vietnamese": "Tôi có thể để áo khoác ở đâu?", "position": 22, "ipa": "/wˌeə kan aɪ pˌʊt maɪ kˈəʊt/"}, {"english": "This hat is brown.", "vietnamese": "Chiếc mũ này màu nâu.", "position": 23, "ipa": "/ðɪs hˈat ɪz bɹˈaʊn/"}, {"english": "I like your new jacket.", "vietnamese": "Tôi thích chiếc áo khoác mới của bạn.", "position": 24, "ipa": "/aɪ lˈaɪk jɔː njˈuː dʒˈakɪt/"}, {"english": "Thank you. It is very warm.", "vietnamese": "Cảm ơn bạn. Nó rất ấm.", "position": 25, "ipa": "/θˈaŋk juː ɪt ɪz vˈɛɹi wˈɔːm/"}, {"english": "I wear a uniform at work.", "vietnamese": "Tôi mặc đồng phục khi đi làm.", "position": 26, "ipa": "/aɪ wˈeəɹ ɐ jˈuːnɪfˌɔːm at wˈɜːk/"}, {"english": "Please take off your shoes.", "vietnamese": "Vui lòng cởi giày ra.", "position": 27, "ipa": "/plˈiːz tˈeɪk ˈɒf jɔː ʃˈuːz/"}, {"english": "Put on your coat.", "vietnamese": "Hãy mặc áo khoác vào.", "position": 28, "ipa": "/pˌʊt ˌɒn jɔː kˈəʊt/"}, {"english": "It is cold outside.", "vietnamese": "Bên ngoài trời lạnh.", "position": 29, "ipa": "/ɪt ɪz kˈəʊld aʊtsˈaɪd/"}, {"english": "These clothes are comfortable.", "vietnamese": "Những bộ quần áo này thoải mái.", "position": 30, "ipa": "/ðiːz klˈəʊðz ɑː kˈʌmftəbəl/"}], "grammar": "Dùng tính từ màu sắc trước danh từ: a blue shirt; hỏi lựa chọn bằng What colour…?", "vocabulary_notes": "shirt: áo sơ mi; shoes: giày; size: cỡ; blue: xanh dương; red: đỏ", "title_vi": "Quần áo và màu sắc"},
{"title": "Lesson 11: Asking for Directions", "sentences": [{"english": "Excuse me, where is the bank?", "vietnamese": "Xin lỗi, ngân hàng ở đâu?", "position": 1, "ipa": "/ɛkskjˈuːs mˌiː wˌeəɹ ɪz ðə bˈaŋk/"}, {"english": "Go straight ahead.", "vietnamese": "Đi thẳng về phía trước.", "position": 2, "ipa": "/ɡˌəʊ stɹˈeɪt ɐhˈɛd/"}, {"english": "Turn left at the traffic lights.", "vietnamese": "Rẽ trái ở chỗ đèn giao thông.", "position": 3, "ipa": "/tˈɜːn lˈɛft at ðə tɹˈafɪk lˈaɪts/"}, {"english": "Turn right at the next street.", "vietnamese": "Rẽ phải ở đường tiếp theo.", "position": 4, "ipa": "/tˈɜːn ɹˈaɪt at ðə nˈɛkst stɹˈiːt/"}, {"english": "The bank is next to the supermarket.", "vietnamese": "Ngân hàng ở cạnh siêu thị.", "position": 5, "ipa": "/ðə bˈaŋk ɪz nˈɛkst tə ðə sˈuːpəmˌɑːkɪt/"}, {"english": "It is opposite the hospital.", "vietnamese": "Nó ở đối diện bệnh viện.", "position": 6, "ipa": "/ɪt ɪz ˈɒpəzˌɪt ðə hˈɒspɪtəl/"}, {"english": "Is it far from here?", "vietnamese": "Chỗ đó có xa đây không?", "position": 7, "ipa": "/ɪz ɪt fˈɑː fɹɒm hˈiə/"}, {"english": "It is about five minutes on foot.", "vietnamese": "Đi bộ mất khoảng năm phút.", "position": 8, "ipa": "/ɪt ɪz ɐbˌaʊt fˈaɪv mˈɪnɪts ˌɒn fˈʊt/"}, {"english": "Can you show me on the map?", "vietnamese": "Bạn có thể chỉ trên bản đồ cho tôi không?", "position": 9, "ipa": "/kan juː ʃˈəʊ mˌiː ɒnðə mˈap/"}, {"english": "Thank you. I understand now.", "vietnamese": "Cảm ơn bạn. Bây giờ tôi hiểu rồi.", "position": 10, "ipa": "/θˈaŋk juː aɪ ˌʌndəstˈand nˈaʊ/"}, {"english": "Where is the nearest pharmacy?", "vietnamese": "Hiệu thuốc gần nhất ở đâu?", "position": 11, "ipa": "/wˌeəɹ ɪz ðə nˌiəɹɪst fˈɑːməsi/"}, {"english": "Is there a cafe near here?", "vietnamese": "Gần đây có quán cà phê nào không?", "position": 12, "ipa": "/ɪz ðeəɹ ɐ kˈafeɪ nˌiə hˈiə/"}, {"english": "Walk past the school.", "vietnamese": "Đi qua trường học.", "position": 13, "ipa": "/wˈɔːk pˈast ðə skˈuːl/"}, {"english": "Cross the road carefully.", "vietnamese": "Hãy sang đường cẩn thận.", "position": 14, "ipa": "/kɹˈɒs ðə ɹˈəʊd kˈeəfəli/"}, {"english": "Take the second road on the left.", "vietnamese": "Rẽ vào con đường thứ hai bên trái.", "position": 15, "ipa": "/tˈeɪk ðə sˈɛkənd ɹˈəʊd ɒnðə lˈɛft/"}, {"english": "The station is on your right.", "vietnamese": "Nhà ga ở bên phải bạn.", "position": 16, "ipa": "/ðə stˈeɪʃən ɪz ˌɒn jɔː ɹˈaɪt/"}, {"english": "It is between the bank and the cafe.", "vietnamese": "Nó nằm giữa ngân hàng và quán cà phê.", "position": 17, "ipa": "/ɪt ɪz bɪtwˌiːn ðə bˈaŋk and ðə kˈafeɪ/"}, {"english": "You cannot miss it.", "vietnamese": "Bạn sẽ dễ dàng nhìn thấy nó.", "position": 18, "ipa": "/juː kˈanɒt mˈɪs ɪt/"}, {"english": "I am looking for the museum.", "vietnamese": "Tôi đang tìm bảo tàng.", "position": 19, "ipa": "/aɪɐm lˈʊkɪŋ fəðə mjuːzˈiəm/"}, {"english": "Am I going the right way?", "vietnamese": "Tôi có đang đi đúng đường không?", "position": 20, "ipa": "/am aɪ ɡˌəʊɪŋ ðə ɹˈaɪt wˈeɪ/"}, {"english": "Yes, keep going straight.", "vietnamese": "Đúng rồi, cứ tiếp tục đi thẳng.", "position": 21, "ipa": "/jˈɛs kˈiːp ɡˌəʊɪŋ stɹˈeɪt/"}, {"english": "No, you need to turn back.", "vietnamese": "Không, bạn cần quay lại.", "position": 22, "ipa": "/nˈəʊ juː nˈiːd tə tˈɜːn bˈak/"}, {"english": "How far is the station?", "vietnamese": "Nhà ga cách đây bao xa?", "position": 23, "ipa": "/hˌaʊ fˈɑːɹ ɪz ðə stˈeɪʃən/"}, {"english": "It is about one kilometre away.", "vietnamese": "Nó cách đây khoảng một ki lô mét.", "position": 24, "ipa": "/ɪt ɪz ɐbˌaʊt wˈɒn kˈɪləmˌiːtəɹ ɐwˈeɪ/"}, {"english": "Can I walk there?", "vietnamese": "Tôi có thể đi bộ đến đó không?", "position": 25, "ipa": "/kan aɪ wˈɔːk ðˈeə/"}, {"english": "The entrance is around the corner.", "vietnamese": "Lối vào ở ngay sau góc đường.", "position": 26, "ipa": "/ðɪ ˈɛntɹəns ɪz ɐɹˈaʊnd ðə kˈɔːnə/"}, {"english": "Please follow me.", "vietnamese": "Vui lòng đi theo tôi.", "position": 27, "ipa": "/plˈiːz fˈɒləʊ mˌiː/"}, {"english": "The lift is next to the stairs.", "vietnamese": "Thang máy ở cạnh cầu thang.", "position": 28, "ipa": "/ðə lˈɪft ɪz nˈɛkst tə ðə stˈeəz/"}, {"english": "Which floor is the office on?", "vietnamese": "Văn phòng ở tầng mấy?", "position": 29, "ipa": "/wˌɪtʃ flˈɔːɹ ɪz ðɪ ˈɒfɪs ˈɒn/"}, {"english": "It is on the second floor.", "vietnamese": "Nó ở tầng hai.", "position": 30, "ipa": "/ɪt ɪz ɒnðə sˈɛkənd flˈɔː/"}], "grammar": "Dùng Where is…? để hỏi địa điểm; dùng động từ đầu câu để chỉ đường.", "vocabulary_notes": "left: trái; right: phải; straight: thẳng; near: gần; opposite: đối diện", "title_vi": "Hỏi đường"},
{"title": "Lesson 12: Getting Around Town", "sentences": [{"english": "I go to work by bus.", "vietnamese": "Tôi đi làm bằng xe buýt.", "position": 1, "ipa": "/aɪ ɡˌəʊ tə wˈɜːk baɪ bˈʌs/"}, {"english": "How do you get to school?", "vietnamese": "Bạn đến trường bằng cách nào?", "position": 2, "ipa": "/hˌaʊ dˈuː juː ɡɛt tə skˈuːl/"}, {"english": "I walk to school.", "vietnamese": "Tôi đi bộ đến trường.", "position": 3, "ipa": "/aɪ wˈɔːk tə skˈuːl/"}, {"english": "Where is the bus stop?", "vietnamese": "Trạm xe buýt ở đâu?", "position": 4, "ipa": "/wˌeəɹ ɪz ðə bˈʌs stˈɒp/"}, {"english": "Does this bus go to the city centre?", "vietnamese": "Xe buýt này có đến trung tâm thành phố không?", "position": 5, "ipa": "/dˈʌz ðɪs bˈʌs ɡˌəʊ tə ðə sˈɪti sˈɛntə/"}, {"english": "I need a ticket to Hanoi.", "vietnamese": "Tôi cần một vé đi Hà Nội.", "position": 6, "ipa": "/aɪ nˈiːd ɐ tˈɪkɪt tə hanˈɔɪ/"}, {"english": "How much is a ticket?", "vietnamese": "Một vé giá bao nhiêu?", "position": 7, "ipa": "/hˌaʊ mˈʌtʃ ɪz ɐ tˈɪkɪt/"}, {"english": "What time does the train leave?", "vietnamese": "Tàu khởi hành lúc mấy giờ?", "position": 8, "ipa": "/wˌɒt tˈaɪm dˈʌz ðə tɹˈeɪn lˈiːv/"}, {"english": "Please stop here.", "vietnamese": "Vui lòng dừng ở đây.", "position": 9, "ipa": "/plˈiːz stˈɒp hˈiə/"}, {"english": "I would like to get off here.", "vietnamese": "Tôi muốn xuống ở đây.", "position": 10, "ipa": "/aɪ wʊd lˈaɪk tə ɡɛt ˈɒf hˈiə/"}, {"english": "Do you take the bus every day?", "vietnamese": "Bạn có đi xe buýt mỗi ngày không?", "position": 11, "ipa": "/dˈuː juː tˈeɪk ðə bˈʌs ˈɛvɹɪ dˈeɪ/"}, {"english": "I usually ride my bike.", "vietnamese": "Tôi thường đi xe đạp.", "position": 12, "ipa": "/aɪ jˈuːʒuːəli ɹˈaɪd maɪ bˈaɪk/"}, {"english": "I sometimes take a taxi.", "vietnamese": "Thỉnh thoảng tôi đi taxi.", "position": 13, "ipa": "/aɪ sˈʌmtaɪmz tˈeɪk ɐ tˈaksi/"}, {"english": "How long does the journey take?", "vietnamese": "Chuyến đi mất bao lâu?", "position": 14, "ipa": "/hˌaʊ lˈɒŋ dˈʌz ðə dʒˈɜːni tˈeɪk/"}, {"english": "It takes about twenty minutes.", "vietnamese": "Mất khoảng hai mươi phút.", "position": 15, "ipa": "/ɪt tˈeɪks ɐbˌaʊt twˈɛnti mˈɪnɪts/"}, {"english": "Where can I buy a bus ticket?", "vietnamese": "Tôi có thể mua vé xe buýt ở đâu?", "position": 16, "ipa": "/wˌeə kan aɪ bˈaɪ ɐ bˈʌs tˈɪkɪt/"}, {"english": "Can I pay on the bus?", "vietnamese": "Tôi có thể trả tiền trên xe buýt không?", "position": 17, "ipa": "/kan aɪ pˈeɪ ɒnðə bˈʌs/"}, {"english": "Is this seat free?", "vietnamese": "Chỗ ngồi này có trống không?", "position": 18, "ipa": "/ɪz ðɪs sˈiːt fɹˈiː/"}, {"english": "Yes, you can sit here.", "vietnamese": "Có, bạn có thể ngồi đây.", "position": 19, "ipa": "/jˈɛs juː kan sˈɪt hˈiə/"}, {"english": "Which bus should I take?", "vietnamese": "Tôi nên đi xe buýt nào?", "position": 20, "ipa": "/wˌɪtʃ bˈʌs ʃˌʊd aɪ tˈeɪk/"}, {"english": "Take the number ten bus.", "vietnamese": "Hãy đi xe buýt số mười.", "position": 21, "ipa": "/tˈeɪk ðə nˈʌmbə tˈɛn bˈʌs/"}, {"english": "The next bus comes in five minutes.", "vietnamese": "Xe buýt tiếp theo sẽ đến trong năm phút nữa.", "position": 22, "ipa": "/ðə nˈɛkst bˈʌs kˈʌmz ɪn fˈaɪv mˈɪnɪts/"}, {"english": "I need to change trains.", "vietnamese": "Tôi cần đổi tàu.", "position": 23, "ipa": "/aɪ nˈiːd tə tʃˈeɪndʒ tɹˈeɪnz/"}, {"english": "Which platform do I need?", "vietnamese": "Tôi cần đến sân ga nào?", "position": 24, "ipa": "/wˌɪtʃ plˈatfɔːm dˈuː aɪ nˈiːd/"}, {"english": "The train is late.", "vietnamese": "Tàu đến muộn.", "position": 25, "ipa": "/ðə tɹˈeɪn ɪz lˈeɪt/"}, {"english": "Please fasten your seat belt.", "vietnamese": "Vui lòng thắt dây an toàn.", "position": 26, "ipa": "/plˈiːz fˈasən jɔː sˈiːt bˈɛlt/"}, {"english": "Can you take me to this address?", "vietnamese": "Bạn có thể đưa tôi đến địa chỉ này không?", "position": 27, "ipa": "/kan juː tˈeɪk mˌiː tə ðɪs ɐdɹˈɛs/"}, {"english": "There is a lot of traffic.", "vietnamese": "Đường rất đông xe.", "position": 28, "ipa": "/ðeəɹ ɪz ɐ lˈɒt ɒv tɹˈafɪk/"}, {"english": "I prefer travelling by train.", "vietnamese": "Tôi thích đi tàu hơn.", "position": 29, "ipa": "/aɪ pɹɪfˈɜː tɹˈavəlɪŋ baɪ tɹˈeɪn/"}, {"english": "Let us leave a little earlier.", "vietnamese": "Chúng ta hãy đi sớm hơn một chút.", "position": 30, "ipa": "/lˈɛt ˌʌs lˈiːv ɐ lˈɪtəl ˈɜːlɪə/"}], "grammar": "Dùng by + phương tiện để nói cách đi lại; dùng How do you get to…? để hỏi.", "vocabulary_notes": "bus: xe buýt; train: tàu; ticket: vé; station: nhà ga; on foot: đi bộ", "title_vi": "Đi lại trong thành phố"},
{"title": "Lesson 13: The Weather", "sentences": [{"english": "What is the weather like today?", "vietnamese": "Hôm nay thời tiết thế nào?", "position": 1, "ipa": "/wˌɒt ɪz ðə wˈɛðə lˈaɪk tədˈeɪ/"}, {"english": "It is sunny.", "vietnamese": "Trời có nắng.", "position": 2, "ipa": "/ɪt ɪz sˈʌni/"}, {"english": "It is very hot today.", "vietnamese": "Hôm nay trời rất nóng.", "position": 3, "ipa": "/ɪt ɪz vˈɛɹi hˈɒt tədˈeɪ/"}, {"english": "It is cold this morning.", "vietnamese": "Sáng nay trời lạnh.", "position": 4, "ipa": "/ɪt ɪz kˈəʊld ðɪs mˈɔːnɪŋ/"}, {"english": "It is raining now.", "vietnamese": "Bây giờ trời đang mưa.", "position": 5, "ipa": "/ɪt ɪz ɹˈeɪnɪŋ nˈaʊ/"}, {"english": "Do you have an umbrella?", "vietnamese": "Bạn có ô không?", "position": 6, "ipa": "/dˈuː juː hav ɐn ʌmbɹˈɛlə/"}, {"english": "I need a warm coat.", "vietnamese": "Tôi cần một chiếc áo khoác ấm.", "position": 7, "ipa": "/aɪ nˈiːd ɐ wˈɔːm kˈəʊt/"}, {"english": "It is windy outside.", "vietnamese": "Bên ngoài trời có gió.", "position": 8, "ipa": "/ɪt ɪz wˈɪndi aʊtsˈaɪd/"}, {"english": "I like cool weather.", "vietnamese": "Tôi thích thời tiết mát mẻ.", "position": 9, "ipa": "/aɪ lˈaɪk kˈuːl wˈɛðə/"}, {"english": "Let us stay inside.", "vietnamese": "Chúng ta hãy ở trong nhà.", "position": 10, "ipa": "/lˈɛt ˌʌs stˈeɪ ɪnsˈaɪd/"}, {"english": "Is it hot in your city?", "vietnamese": "Thành phố của bạn có nóng không?", "position": 11, "ipa": "/ɪz ɪt hˈɒt ɪn jɔː sˈɪti/"}, {"english": "It is warm in spring.", "vietnamese": "Trời ấm vào mùa xuân.", "position": 12, "ipa": "/ɪt ɪz wˈɔːm ɪn spɹˈɪŋ/"}, {"english": "It is hot in summer.", "vietnamese": "Trời nóng vào mùa hè.", "position": 13, "ipa": "/ɪt ɪz hˈɒt ɪn sˈʌmə/"}, {"english": "It is cool in autumn.", "vietnamese": "Trời mát vào mùa thu.", "position": 14, "ipa": "/ɪt ɪz kˈuːl ɪn ˈɔːtʌm/"}, {"english": "It is cold in winter.", "vietnamese": "Trời lạnh vào mùa đông.", "position": 15, "ipa": "/ɪt ɪz kˈəʊld ɪn wˈɪntə/"}, {"english": "What is your favourite season?", "vietnamese": "Mùa yêu thích của bạn là gì?", "position": 16, "ipa": "/wˌɒt ɪz jɔː fˈeɪvɹɪt sˈiːzən/"}, {"english": "I like spring best.", "vietnamese": "Tôi thích mùa xuân nhất.", "position": 17, "ipa": "/aɪ lˈaɪk spɹˈɪŋ bˈɛst/"}, {"english": "The sky is cloudy.", "vietnamese": "Trời nhiều mây.", "position": 18, "ipa": "/ðə skˈaɪ ɪz klˈaʊdi/"}, {"english": "There is a lot of rain today.", "vietnamese": "Hôm nay trời mưa nhiều.", "position": 19, "ipa": "/ðeəɹ ɪz ɐ lˈɒt ɒv ɹˈeɪn tədˈeɪ/"}, {"english": "Take your umbrella with you.", "vietnamese": "Hãy mang ô theo.", "position": 20, "ipa": "/tˈeɪk jɔːɹ ʌmbɹˈɛlə wɪð juː/"}, {"english": "Do you think it will rain?", "vietnamese": "Bạn có nghĩ trời sẽ mưa không?", "position": 21, "ipa": "/dˈuː juː θˈɪŋk ɪt wɪl ɹˈeɪn/"}, {"english": "I think it will be sunny tomorrow.", "vietnamese": "Tôi nghĩ ngày mai trời sẽ nắng.", "position": 22, "ipa": "/aɪ θˈɪŋk ɪt wɪl biː sˈʌni təmˈɒɹəʊ/"}, {"english": "The weather is lovely today.", "vietnamese": "Hôm nay thời tiết rất đẹp.", "position": 23, "ipa": "/ðə wˈɛðəɹ ɪz lˈʌvli tədˈeɪ/"}, {"english": "Let us go for a walk.", "vietnamese": "Chúng ta hãy đi dạo.", "position": 24, "ipa": "/lˈɛt ˌʌs ɡˌəʊ fəɹə wˈɔːk/"}, {"english": "I do not like very hot weather.", "vietnamese": "Tôi không thích thời tiết quá nóng.", "position": 25, "ipa": "/aɪ duːnˌɒt lˈaɪk vˈɛɹi hˈɒt wˈɛðə/"}, {"english": "How cold is it outside?", "vietnamese": "Bên ngoài lạnh đến mức nào?", "position": 26, "ipa": "/hˌaʊ kˈəʊld ɪz ɪt aʊtsˈaɪd/"}, {"english": "It is about ten degrees.", "vietnamese": "Nhiệt độ khoảng mười độ.", "position": 27, "ipa": "/ɪt ɪz ɐbˌaʊt tˈɛn dɪɡɹˈiːz/"}, {"english": "There is snow on the mountains.", "vietnamese": "Có tuyết trên núi.", "position": 28, "ipa": "/ðeəɹ ɪz snˈəʊ ɒnðə mˈaʊntɪnz/"}, {"english": "The rain is stopping.", "vietnamese": "Mưa đang tạnh.", "position": 29, "ipa": "/ðə ɹˈeɪn ɪz stˈɒpɪŋ/"}, {"english": "Look at the rainbow!", "vietnamese": "Nhìn cầu vồng kìa!", "position": 30, "ipa": "/lˈʊk at ðə ɹˈeɪnbəʊ/"}], "grammar": "Dùng It is + tính từ để mô tả thời tiết; hỏi bằng What is the weather like?", "vocabulary_notes": "weather: thời tiết; sunny: có nắng; rainy: có mưa; cold: lạnh; umbrella: ô", "title_vi": "Thời tiết"},
{"title": "Lesson 14: Hobbies and Free Time", "sentences": [{"english": "What do you do in your free time?", "vietnamese": "Bạn làm gì trong thời gian rảnh?", "position": 1, "ipa": "/wˌɒt dˈuː juː dˈuː ɪn jɔː fɹˈiː tˈaɪm/"}, {"english": "I like reading books.", "vietnamese": "Tôi thích đọc sách.", "position": 2, "ipa": "/aɪ lˈaɪk ɹˈiːdɪŋ bˈʊks/"}, {"english": "I listen to music every day.", "vietnamese": "Tôi nghe nhạc mỗi ngày.", "position": 3, "ipa": "/aɪ lˈɪsən tə mjˈuːzɪk ˈɛvɹɪ dˈeɪ/"}, {"english": "Do you like playing football?", "vietnamese": "Bạn có thích chơi bóng đá không?", "position": 4, "ipa": "/dˈuː juː lˈaɪk plˈeɪɪŋ fˈʊtbɔːl/"}, {"english": "I play football on Sundays.", "vietnamese": "Tôi chơi bóng đá vào các ngày Chủ nhật.", "position": 5, "ipa": "/aɪ plˈeɪ fˈʊtbɔːl ˌɒn sˈʌndeɪz/"}, {"english": "Can you swim?", "vietnamese": "Bạn có biết bơi không?", "position": 6, "ipa": "/kan juː swˈɪm/"}, {"english": "Yes, I can swim.", "vietnamese": "Có, tôi biết bơi.", "position": 7, "ipa": "/jˈɛs aɪ kan swˈɪm/"}, {"english": "I enjoy cooking.", "vietnamese": "Tôi thích nấu ăn.", "position": 8, "ipa": "/aɪ ɛndʒˈɔɪ kˈʊkɪŋ/"}, {"english": "My hobby is taking photos.", "vietnamese": "Sở thích của tôi là chụp ảnh.", "position": 9, "ipa": "/maɪ hˈɒbi ɪz tˈeɪkɪŋ fˈəʊtəʊz/"}, {"english": "Would you like to join us?", "vietnamese": "Bạn có muốn tham gia cùng chúng tôi không?", "position": 10, "ipa": "/wʊd juː lˈaɪk tə dʒˈɔɪn ˌʌs/"}, {"english": "Do you play a musical instrument?", "vietnamese": "Bạn có chơi nhạc cụ nào không?", "position": 11, "ipa": "/dˈuː juː plˈeɪ ɐ mjˈuːzɪkəl ˈɪnstɹəmənt/"}, {"english": "I play the guitar.", "vietnamese": "Tôi chơi ghi ta.", "position": 12, "ipa": "/aɪ plˈeɪ ðə ɡɪtˈɑː/"}, {"english": "I am learning to play the piano.", "vietnamese": "Tôi đang học chơi đàn pi a nô.", "position": 13, "ipa": "/aɪɐm lˈɜːnɪŋ tə plˈeɪ ðə piˈanəʊ/"}, {"english": "I watch films at the weekend.", "vietnamese": "Tôi xem phim vào cuối tuần.", "position": 14, "ipa": "/aɪ wˈɒtʃ fˈɪlmz at ðə wiːkˈɛnd/"}, {"english": "What kind of music do you like?", "vietnamese": "Bạn thích loại nhạc nào?", "position": 15, "ipa": "/wˌɒt kˈaɪnd ɒv mjˈuːzɪk dˈuː juː lˈaɪk/"}, {"english": "I like pop music.", "vietnamese": "Tôi thích nhạc pop.", "position": 16, "ipa": "/aɪ lˈaɪk pˈɒp mjˈuːzɪk/"}, {"english": "Do you enjoy dancing?", "vietnamese": "Bạn có thích nhảy không?", "position": 17, "ipa": "/dˈuː juː ɛndʒˈɔɪ dˈansɪŋ/"}, {"english": "I like drawing pictures.", "vietnamese": "Tôi thích vẽ tranh.", "position": 18, "ipa": "/aɪ lˈaɪk dɹˈɔːɪŋ pˈɪktʃəz/"}, {"english": "I go running in the morning.", "vietnamese": "Tôi chạy bộ vào buổi sáng.", "position": 19, "ipa": "/aɪ ɡˌəʊ ɹˈʌnɪŋ ɪnðə mˈɔːnɪŋ/"}, {"english": "My friends and I play badminton.", "vietnamese": "Tôi và các bạn chơi cầu lông.", "position": 20, "ipa": "/maɪ fɹˈɛndz and aɪ plˈeɪ bˈadmɪntən/"}, {"english": "How often do you exercise?", "vietnamese": "Bạn tập thể dục thường xuyên thế nào?", "position": 21, "ipa": "/hˌaʊ ˈɒfən dˈuː juː ˈɛksəsˌaɪz/"}, {"english": "I exercise three times a week.", "vietnamese": "Tôi tập thể dục ba lần một tuần.", "position": 22, "ipa": "/aɪ ˈɛksəsˌaɪz θɹˈiː tˈaɪmz ɐ wˈiːk/"}, {"english": "I like spending time outside.", "vietnamese": "Tôi thích dành thời gian ở ngoài trời.", "position": 23, "ipa": "/aɪ lˈaɪk spˈɛndɪŋ tˈaɪm aʊtsˈaɪd/"}, {"english": "I collect postcards.", "vietnamese": "Tôi sưu tầm bưu thiếp.", "position": 24, "ipa": "/aɪ kəlˈɛkt pˈəʊstkɑːdz/"}, {"english": "What are you reading?", "vietnamese": "Bạn đang đọc gì?", "position": 25, "ipa": "/wˌɒt ɑː juː ɹˈiːdɪŋ/"}, {"english": "I am reading a short story.", "vietnamese": "Tôi đang đọc một truyện ngắn.", "position": 26, "ipa": "/aɪɐm ɹˈiːdɪŋ ɐ ʃˈɔːt stˈɔːɹi/"}, {"english": "Can you teach me to swim?", "vietnamese": "Bạn có thể dạy tôi bơi không?", "position": 27, "ipa": "/kan juː tˈiːtʃ mˌiː tə swˈɪm/"}, {"english": "Let us try something new.", "vietnamese": "Chúng ta hãy thử điều gì đó mới.", "position": 28, "ipa": "/lˈɛt ˌʌs tɹˈaɪ sˈʌmθɪŋ njˈuː/"}, {"english": "I am not very good at tennis.", "vietnamese": "Tôi chơi quần vợt chưa giỏi lắm.", "position": 29, "ipa": "/aɪɐm nˌɒt vˈɛɹi ɡˈʊd at tˈɛnɪs/"}, {"english": "It is fun to learn together.", "vietnamese": "Học cùng nhau thật vui.", "position": 30, "ipa": "/ɪt ɪz fˈʌn tə lˈɜːn təɡˈɛðə/"}], "grammar": "Dùng like + V-ing để nói sở thích; dùng can + động từ nguyên mẫu để nói khả năng.", "vocabulary_notes": "hobby: sở thích; read: đọc; swim: bơi; music: âm nhạc; free time: thời gian rảnh", "title_vi": "Sở thích và thời gian rảnh"},
{"title": "Lesson 15: Jobs and Workplaces", "sentences": [{"english": "What do you do?", "vietnamese": "Bạn làm nghề gì?", "position": 1, "ipa": "/wˌɒt dˈuː juː dˈuː/"}, {"english": "I am a teacher.", "vietnamese": "Tôi là giáo viên.", "position": 2, "ipa": "/aɪɐm ɐ tˈiːtʃə/"}, {"english": "She is a nurse.", "vietnamese": "Cô ấy là y tá.", "position": 3, "ipa": "/ʃiː ɪz ɐ nˈɜːs/"}, {"english": "He is an engineer.", "vietnamese": "Anh ấy là kỹ sư.", "position": 4, "ipa": "/hiː ɪz ɐn ˌɛndʒɪnˈiə/"}, {"english": "Where do you work?", "vietnamese": "Bạn làm việc ở đâu?", "position": 5, "ipa": "/wˌeə dˈuː juː wˈɜːk/"}, {"english": "I work in an office.", "vietnamese": "Tôi làm việc ở văn phòng.", "position": 6, "ipa": "/aɪ wˈɜːk ɪn ɐn ˈɒfɪs/"}, {"english": "My office is near my home.", "vietnamese": "Văn phòng của tôi ở gần nhà.", "position": 7, "ipa": "/maɪ ˈɒfɪs ɪz nˌiə maɪ hˈəʊm/"}, {"english": "I start work at nine.", "vietnamese": "Tôi bắt đầu làm việc lúc chín giờ.", "position": 8, "ipa": "/aɪ stˈɑːt wˈɜːk at nˈaɪn/"}, {"english": "I finish work at five.", "vietnamese": "Tôi kết thúc công việc lúc năm giờ.", "position": 9, "ipa": "/aɪ fˈɪnɪʃ wˈɜːk at fˈaɪv/"}, {"english": "My colleagues are friendly.", "vietnamese": "Đồng nghiệp của tôi rất thân thiện.", "position": 10, "ipa": "/maɪ kˈɒliːɡz ɑː fɹˈɛndli/"}, {"english": "Do you like your job?", "vietnamese": "Bạn có thích công việc của mình không?", "position": 11, "ipa": "/dˈuː juː lˈaɪk jɔː dʒˈɒb/"}, {"english": "Yes, I enjoy helping people.", "vietnamese": "Có, tôi thích giúp đỡ mọi người.", "position": 12, "ipa": "/jˈɛs aɪ ɛndʒˈɔɪ hˈɛlpɪŋ pˈiːpəl/"}, {"english": "My sister works in a bank.", "vietnamese": "Chị gái tôi làm việc ở ngân hàng.", "position": 13, "ipa": "/maɪ sˈɪstə wˈɜːks ɪn ɐ bˈaŋk/"}, {"english": "My brother is a chef.", "vietnamese": "Anh trai tôi là đầu bếp.", "position": 14, "ipa": "/maɪ bɹˈʌðəɹ ɪz ɐ ʃˈɛf/"}, {"english": "I work from Monday to Friday.", "vietnamese": "Tôi làm việc từ thứ Hai đến thứ Sáu.", "position": 15, "ipa": "/aɪ wˈɜːk fɹɒm mˈʌndeɪ tə fɹˈaɪdeɪ/"}, {"english": "I do not work on Sundays.", "vietnamese": "Tôi không làm việc vào Chủ nhật.", "position": 16, "ipa": "/aɪ duːnˌɒt wˈɜːk ˌɒn sˈʌndeɪz/"}, {"english": "What time is your lunch break?", "vietnamese": "Giờ nghỉ trưa của bạn là mấy giờ?", "position": 17, "ipa": "/wˌɒt tˈaɪm ɪz jɔː lˈʌntʃ bɹˈeɪk/"}, {"english": "I have lunch at twelve.", "vietnamese": "Tôi ăn trưa lúc mười hai giờ.", "position": 18, "ipa": "/aɪ hav lˈʌntʃ at twˈɛlv/"}, {"english": "I work with a small team.", "vietnamese": "Tôi làm việc trong một nhóm nhỏ.", "position": 19, "ipa": "/aɪ wˈɜːk wɪð ɐ smˈɔːl tˈiːm/"}, {"english": "Can you help me with this task?", "vietnamese": "Bạn có thể giúp tôi làm việc này không?", "position": 20, "ipa": "/kan juː hˈɛlp mˌiː wɪð ðɪs tˈask/"}, {"english": "I need to send an email.", "vietnamese": "Tôi cần gửi một email.", "position": 21, "ipa": "/aɪ nˈiːd tə sˈɛnd ɐn ˈiːmeɪl/"}, {"english": "We have a meeting at ten.", "vietnamese": "Chúng tôi có cuộc họp lúc mười giờ.", "position": 22, "ipa": "/wiː hav ɐ mˈiːtɪŋ at tˈɛn/"}, {"english": "The meeting room is upstairs.", "vietnamese": "Phòng họp ở tầng trên.", "position": 23, "ipa": "/ðə mˈiːtɪŋ ɹˈuːm ɪz ʌpstˈeəz/"}, {"english": "Can I speak to the manager?", "vietnamese": "Tôi có thể nói chuyện với quản lý không?", "position": 24, "ipa": "/kan aɪ spˈiːk tə ðə mˈanɪdʒə/"}, {"english": "She is busy at the moment.", "vietnamese": "Hiện tại cô ấy đang bận.", "position": 25, "ipa": "/ʃiː ɪz bˈɪzi at ðə mˈəʊmənt/"}, {"english": "Please leave a message.", "vietnamese": "Vui lòng để lại lời nhắn.", "position": 26, "ipa": "/plˈiːz lˈiːv ɐ mˈɛsɪdʒ/"}, {"english": "I am on a break.", "vietnamese": "Tôi đang nghỉ giải lao.", "position": 27, "ipa": "/aɪɐm ˌɒn ɐ bɹˈeɪk/"}, {"english": "I have a day off tomorrow.", "vietnamese": "Ngày mai tôi được nghỉ làm.", "position": 28, "ipa": "/aɪ hav ɐ dˈeɪ ˈɒf təmˈɒɹəʊ/"}, {"english": "I am looking for a job.", "vietnamese": "Tôi đang tìm việc.", "position": 29, "ipa": "/aɪɐm lˈʊkɪŋ fəɹə dʒˈɒb/"}, {"english": "I would like to work in a hotel.", "vietnamese": "Tôi muốn làm việc ở khách sạn.", "position": 30, "ipa": "/aɪ wʊd lˈaɪk tə wˈɜːk ɪn ɐ həʊtˈɛl/"}], "grammar": "Hỏi nghề bằng What do you do? Dùng a/an trước tên nghề số ít.", "vocabulary_notes": "job: nghề nghiệp; office: văn phòng; teacher: giáo viên; nurse: y tá; colleague: đồng nghiệp", "title_vi": "Nghề nghiệp và nơi làm việc"},
{"title": "Lesson 16: In the Classroom", "sentences": [{"english": "Please open your book.", "vietnamese": "Vui lòng mở sách ra.", "position": 1, "ipa": "/plˈiːz ˈəʊpən jɔː bˈʊk/"}, {"english": "Please listen carefully.", "vietnamese": "Vui lòng lắng nghe kỹ.", "position": 2, "ipa": "/plˈiːz lˈɪsən kˈeəfəli/"}, {"english": "Can you repeat that, please?", "vietnamese": "Bạn có thể nhắc lại điều đó không?", "position": 3, "ipa": "/kan juː ɹɪpˈiːt ðˈat plˈiːz/"}, {"english": "Please speak more slowly.", "vietnamese": "Vui lòng nói chậm hơn.", "position": 4, "ipa": "/plˈiːz spˈiːk mˈɔː slˈəʊli/"}, {"english": "I do not understand this word.", "vietnamese": "Tôi không hiểu từ này.", "position": 5, "ipa": "/aɪ duːnˌɒt ˌʌndəstˈand ðɪs wˈɜːd/"}, {"english": "What does this word mean?", "vietnamese": "Từ này có nghĩa là gì?", "position": 6, "ipa": "/wˌɒt dˈʌz ðɪs wˈɜːd mˈiːn/"}, {"english": "How do you spell your name?", "vietnamese": "Bạn đánh vần tên mình như thế nào?", "position": 7, "ipa": "/hˌaʊ dˈuː juː spˈɛl jɔː nˈeɪm/"}, {"english": "Can I ask a question?", "vietnamese": "Tôi có thể hỏi một câu không?", "position": 8, "ipa": "/kan aɪ ˈask ɐ kwˈɛstʃən/"}, {"english": "May I come in?", "vietnamese": "Em có thể vào lớp không?", "position": 9, "ipa": "/mˈeɪ aɪ kˈʌm ˈɪn/"}, {"english": "Thank you for explaining.", "vietnamese": "Cảm ơn bạn đã giải thích.", "position": 10, "ipa": "/θˈaŋk juː fɔːɹ ɛksplˈeɪnɪŋ/"}, {"english": "What page are we on?", "vietnamese": "Chúng ta đang học ở trang nào?", "position": 11, "ipa": "/wˌɒt pˈeɪdʒ ɑː wiː ˈɒn/"}, {"english": "We are on page twelve.", "vietnamese": "Chúng ta đang ở trang mười hai.", "position": 12, "ipa": "/wiː ɑːɹ ˌɒn pˈeɪdʒ twˈɛlv/"}, {"english": "Please work in pairs.", "vietnamese": "Vui lòng làm việc theo cặp.", "position": 13, "ipa": "/plˈiːz wˈɜːk ɪn pˈeəz/"}, {"english": "Take turns asking questions.", "vietnamese": "Hãy thay phiên nhau đặt câu hỏi.", "position": 14, "ipa": "/tˈeɪk tˈɜːnz ˈaskɪŋ kwˈɛstʃənz/"}, {"english": "Write your answer here.", "vietnamese": "Viết câu trả lời của bạn ở đây.", "position": 15, "ipa": "/ɹˈaɪt jɔːɹ ˈansə hˈiə/"}, {"english": "Can I borrow a pen?", "vietnamese": "Tôi có thể mượn một chiếc bút không?", "position": 16, "ipa": "/kan aɪ bˈɒɹəʊ ɐ pˈɛn/"}, {"english": "Here you are.", "vietnamese": "Của bạn đây.", "position": 17, "ipa": "/hˈiə juː ɑː/"}, {"english": "Please look at the board.", "vietnamese": "Vui lòng nhìn lên bảng.", "position": 18, "ipa": "/plˈiːz lˈʊk at ðə bˈɔːd/"}, {"english": "Is this answer right?", "vietnamese": "Câu trả lời này có đúng không?", "position": 19, "ipa": "/ɪz ðɪs ˈansə ɹˈaɪt/"}, {"english": "Please check your spelling.", "vietnamese": "Vui lòng kiểm tra chính tả.", "position": 20, "ipa": "/plˈiːz tʃˈɛk jɔː spˈɛlɪŋ/"}, {"english": "How do you say this in English?", "vietnamese": "Điều này nói bằng tiếng Anh như thế nào?", "position": 21, "ipa": "/hˌaʊ dˈuː juː sˈeɪ ðɪs ɪn ˈɪŋɡlɪʃ/"}, {"english": "Can you give me an example?", "vietnamese": "Bạn có thể cho tôi một ví dụ không?", "position": 22, "ipa": "/kan juː ɡˈɪv mˌiː ɐn ɛɡzˈampəl/"}, {"english": "I have finished the exercise.", "vietnamese": "Tôi đã làm xong bài tập.", "position": 23, "ipa": "/aɪ hav fˈɪnɪʃt ðɪ ˈɛksəsˌaɪz/"}, {"english": "I need a little more time.", "vietnamese": "Tôi cần thêm một chút thời gian.", "position": 24, "ipa": "/aɪ nˈiːd ɐ lˈɪtəl mˈɔː tˈaɪm/"}, {"english": "Let us practise together.", "vietnamese": "Chúng ta hãy luyện tập cùng nhau.", "position": 25, "ipa": "/lˈɛt ˌʌs pɹˈaktɪs təɡˈɛðə/"}, {"english": "Please put your phone away.", "vietnamese": "Vui lòng cất điện thoại đi.", "position": 26, "ipa": "/plˈiːz pˌʊt jɔː fˈəʊn ɐwˈeɪ/"}, {"english": "What is our homework?", "vietnamese": "Bài tập về nhà của chúng ta là gì?", "position": 27, "ipa": "/wˌɒt ɪz ˌaʊə hˈəʊmwɜːk/"}, {"english": "Read the first two pages.", "vietnamese": "Hãy đọc hai trang đầu tiên.", "position": 28, "ipa": "/ɹˈiːd ðə fˈɜːst tˈuː pˈeɪdʒɪz/"}, {"english": "When is the next lesson?", "vietnamese": "Buổi học tiếp theo là khi nào?", "position": 29, "ipa": "/wˌɛn ɪz ðə nˈɛkst lˈɛsən/"}, {"english": "The lesson ends at four.", "vietnamese": "Buổi học kết thúc lúc bốn giờ.", "position": 30, "ipa": "/ðə lˈɛsən ˈɛndz at fˈɔː/"}], "grammar": "Dùng Can you…? để đề nghị hỗ trợ; dùng Please + động từ để đưa yêu cầu lịch sự.", "vocabulary_notes": "classroom: lớp học; repeat: nhắc lại; spell: đánh vần; question: câu hỏi; slowly: chậm", "title_vi": "Trong lớp học"},
{"title": "Lesson 17: Health and the Body", "sentences": [{"english": "I do not feel well.", "vietnamese": "Tôi thấy không khỏe.", "position": 1, "ipa": "/aɪ duːnˌɒt fˈiːl wˈɛl/"}, {"english": "I have a headache.", "vietnamese": "Tôi bị đau đầu.", "position": 2, "ipa": "/aɪ hav ɐ hˈɛdeɪk/"}, {"english": "I have a sore throat.", "vietnamese": "Tôi bị đau họng.", "position": 3, "ipa": "/aɪ hav ɐ sˈɔː θɹˈəʊt/"}, {"english": "My stomach hurts.", "vietnamese": "Tôi bị đau bụng.", "position": 4, "ipa": "/maɪ stˈʌmək hˈɜːts/"}, {"english": "Do you have a fever?", "vietnamese": "Bạn có bị sốt không?", "position": 5, "ipa": "/dˈuː juː hav ɐ fˈiːvə/"}, {"english": "I need to see a doctor.", "vietnamese": "Tôi cần gặp bác sĩ.", "position": 6, "ipa": "/aɪ nˈiːd tə sˈiː ɐ dˈɒktə/"}, {"english": "Where is the nearest clinic?", "vietnamese": "Phòng khám gần nhất ở đâu?", "position": 7, "ipa": "/wˌeəɹ ɪz ðə nˌiəɹɪst klˈɪnɪk/"}, {"english": "I need some water.", "vietnamese": "Tôi cần ít nước.", "position": 8, "ipa": "/aɪ nˈiːd sˌʌm wˈɔːtə/"}, {"english": "I want to rest.", "vietnamese": "Tôi muốn nghỉ ngơi.", "position": 9, "ipa": "/aɪ wˈɒnt tə ɹˈɛst/"}, {"english": "I feel better now.", "vietnamese": "Bây giờ tôi thấy đỡ hơn.", "position": 10, "ipa": "/aɪ fˈiːl bˈɛtə nˈaʊ/"}, {"english": "What is the matter?", "vietnamese": "Bạn bị làm sao vậy?", "position": 11, "ipa": "/wˌɒt ɪz ðə mˈatə/"}, {"english": "I have a cold.", "vietnamese": "Tôi bị cảm.", "position": 12, "ipa": "/aɪ hav ɐ kˈəʊld/"}, {"english": "I have a cough.", "vietnamese": "Tôi bị ho.", "position": 13, "ipa": "/aɪ hav ɐ kˈɒf/"}, {"english": "My back hurts.", "vietnamese": "Lưng tôi bị đau.", "position": 14, "ipa": "/maɪ bˈak hˈɜːts/"}, {"english": "My leg hurts.", "vietnamese": "Chân tôi bị đau.", "position": 15, "ipa": "/maɪ lˈɛɡ hˈɜːts/"}, {"english": "I feel dizzy.", "vietnamese": "Tôi cảm thấy chóng mặt.", "position": 16, "ipa": "/aɪ fˈiːl dˈɪzi/"}, {"english": "How long have you felt like this?", "vietnamese": "Bạn cảm thấy như vậy bao lâu rồi?", "position": 17, "ipa": "/hˌaʊ lˈɒŋ hav juː fˈɛlt lˈaɪk ðˈɪs/"}, {"english": "Since this morning.", "vietnamese": "Từ sáng nay.", "position": 18, "ipa": "/sˈɪns ðɪs mˈɔːnɪŋ/"}, {"english": "Do you have an appointment?", "vietnamese": "Bạn có lịch hẹn không?", "position": 19, "ipa": "/dˈuː juː hav ɐn ɐpˈɔɪntmənt/"}, {"english": "I have an appointment at two.", "vietnamese": "Tôi có lịch hẹn lúc hai giờ.", "position": 20, "ipa": "/aɪ hav ɐn ɐpˈɔɪntmənt at tˈuː/"}, {"english": "Please take a seat.", "vietnamese": "Vui lòng ngồi xuống.", "position": 21, "ipa": "/plˈiːz tˈeɪk ɐ sˈiːt/"}, {"english": "Can you describe the pain?", "vietnamese": "Bạn có thể mô tả cơn đau không?", "position": 22, "ipa": "/kan juː dɪskɹˈaɪb ðə pˈeɪn/"}, {"english": "It hurts when I walk.", "vietnamese": "Tôi thấy đau khi đi bộ.", "position": 23, "ipa": "/ɪt hˈɜːts wɛn aɪ wˈɔːk/"}, {"english": "I am allergic to this medicine.", "vietnamese": "Tôi bị dị ứng với thuốc này.", "position": 24, "ipa": "/aɪɐm ɐlˈɜːdʒɪk tə ðɪs mˈɛdsən/"}, {"english": "Please speak slowly.", "vietnamese": "Vui lòng nói chậm.", "position": 25, "ipa": "/plˈiːz spˈiːk slˈəʊli/"}, {"english": "Where is the pharmacy?", "vietnamese": "Hiệu thuốc ở đâu?", "position": 26, "ipa": "/wˌeəɹ ɪz ðə fˈɑːməsi/"}, {"english": "Can you write that down?", "vietnamese": "Bạn có thể viết điều đó ra không?", "position": 27, "ipa": "/kan juː ɹˈaɪt ðat dˈaʊn/"}, {"english": "I need to call my family.", "vietnamese": "Tôi cần gọi cho gia đình.", "position": 28, "ipa": "/aɪ nˈiːd tə kˈɔːl maɪ fˈamɪli/"}, {"english": "Thank you for your care.", "vietnamese": "Cảm ơn bạn đã chăm sóc tôi.", "position": 29, "ipa": "/θˈaŋk juː fɔː jɔː kˈeə/"}, {"english": "I am ready to go home.", "vietnamese": "Tôi đã sẵn sàng về nhà.", "position": 30, "ipa": "/aɪɐm ɹˈɛdi tə ɡˌəʊ hˈəʊm/"}], "grammar": "Dùng I have + triệu chứng; dùng My + bộ phận cơ thể + hurts để nói chỗ đau.", "vocabulary_notes": "headache: đau đầu; sore throat: đau họng; fever: sốt; doctor: bác sĩ; rest: nghỉ ngơi", "title_vi": "Sức khỏe và cơ thể"},
{"title": "Lesson 18: Feelings and Emotions", "sentences": [{"english": "How do you feel today?", "vietnamese": "Hôm nay bạn cảm thấy thế nào?", "position": 1, "ipa": "/hˌaʊ dˈuː juː fˈiːl tədˈeɪ/"}, {"english": "I feel happy.", "vietnamese": "Tôi cảm thấy vui.", "position": 2, "ipa": "/aɪ fˈiːl hˈapi/"}, {"english": "I am a little tired.", "vietnamese": "Tôi hơi mệt.", "position": 3, "ipa": "/aɪɐm ɐ lˈɪtəl tˈaɪəd/"}, {"english": "Are you worried?", "vietnamese": "Bạn có đang lo lắng không?", "position": 4, "ipa": "/ɑː juː wˈʌɹid/"}, {"english": "I am worried about my exam.", "vietnamese": "Tôi lo lắng về kỳ thi của mình.", "position": 5, "ipa": "/aɪɐm wˈʌɹid ɐbˌaʊt maɪ ɛɡzˈam/"}, {"english": "She is excited about the trip.", "vietnamese": "Cô ấy hào hứng với chuyến đi.", "position": 6, "ipa": "/ʃiː ɪz ɛksˈaɪtɪd ɐbˌaʊt ðə tɹˈɪp/"}, {"english": "I am sad because my friend is leaving.", "vietnamese": "Tôi buồn vì bạn tôi sắp đi xa.", "position": 7, "ipa": "/aɪɐm sˈad bɪkˈɒz maɪ fɹˈɛnd ɪz lˈiːvɪŋ/"}, {"english": "I feel better after a walk.", "vietnamese": "Tôi cảm thấy tốt hơn sau khi đi bộ.", "position": 8, "ipa": "/aɪ fˈiːl bˈɛtəɹ ˈaftəɹ ɐ wˈɔːk/"}, {"english": "Do you want to talk?", "vietnamese": "Bạn có muốn nói chuyện không?", "position": 9, "ipa": "/dˈuː juː wˈɒnt tə tˈɔːk/"}, {"english": "I am here to listen.", "vietnamese": "Tôi ở đây để lắng nghe.", "position": 10, "ipa": "/aɪɐm hˈiə tə lˈɪsən/"}, {"english": "I am excited to see you.", "vietnamese": "Tôi rất hào hứng khi gặp bạn.", "position": 11, "ipa": "/aɪɐm ɛksˈaɪtɪd tə sˈiː juː/"}, {"english": "He looks happy today.", "vietnamese": "Hôm nay anh ấy trông vui vẻ.", "position": 12, "ipa": "/hiː lˈʊks hˈapi tədˈeɪ/"}, {"english": "She feels lonely.", "vietnamese": "Cô ấy cảm thấy cô đơn.", "position": 13, "ipa": "/ʃiː fˈiːlz lˈəʊnli/"}, {"english": "I feel nervous before a test.", "vietnamese": "Tôi thấy lo lắng trước bài kiểm tra.", "position": 14, "ipa": "/aɪ fˈiːl nˈɜːvəs bɪfˌɔːɹ ɐ tˈɛst/"}, {"english": "It is okay to feel nervous.", "vietnamese": "Cảm thấy lo lắng là chuyện bình thường.", "position": 15, "ipa": "/ɪt ɪz əʊkˈeɪ tə fˈiːl nˈɜːvəs/"}, {"english": "I am proud of you.", "vietnamese": "Tôi tự hào về bạn.", "position": 16, "ipa": "/aɪɐm pɹˈaʊd ɒv juː/"}, {"english": "Are you feeling better?", "vietnamese": "Bạn có thấy đỡ hơn không?", "position": 17, "ipa": "/ɑː juː fˈiːlɪŋ bˈɛtə/"}, {"english": "I need a quiet moment.", "vietnamese": "Tôi cần một chút yên tĩnh.", "position": 18, "ipa": "/aɪ nˈiːd ɐ kwˈaɪət mˈəʊmənt/"}, {"english": "Would you like some company?", "vietnamese": "Bạn có muốn có người ở bên không?", "position": 19, "ipa": "/wʊd juː lˈaɪk sˌʌm kˈʌmpəni/"}, {"english": "Thank you for listening.", "vietnamese": "Cảm ơn bạn đã lắng nghe.", "position": 20, "ipa": "/θˈaŋk juː fɔː lˈɪsənɪŋ/"}, {"english": "I am surprised by the news.", "vietnamese": "Tôi ngạc nhiên trước tin đó.", "position": 21, "ipa": "/aɪɐm səpɹˈaɪzd baɪ ðə njˈuːz/"}, {"english": "I feel calm now.", "vietnamese": "Bây giờ tôi cảm thấy bình tĩnh.", "position": 22, "ipa": "/aɪ fˈiːl kˈɑːm nˈaʊ/"}, {"english": "Music helps me relax.", "vietnamese": "Âm nhạc giúp tôi thư giãn.", "position": 23, "ipa": "/mjˈuːzɪk hˈɛlps mˌiː ɹɪlˈaks/"}, {"english": "A walk makes me feel good.", "vietnamese": "Đi bộ khiến tôi thấy dễ chịu.", "position": 24, "ipa": "/ɐ wˈɔːk mˌeɪks mˌiː fˈiːl ɡˈʊd/"}, {"english": "I am angry about the mistake.", "vietnamese": "Tôi tức giận về sai sót đó.", "position": 25, "ipa": "/aɪɐm ˈaŋɡɹi ɐbˌaʊt ðə mɪstˈeɪk/"}, {"english": "Let us take a short break.", "vietnamese": "Chúng ta hãy nghỉ một lát.", "position": 26, "ipa": "/lˈɛt ˌʌs tˈeɪk ɐ ʃˈɔːt bɹˈeɪk/"}, {"english": "You look tired.", "vietnamese": "Bạn trông mệt mỏi.", "position": 27, "ipa": "/juː lˈʊk tˈaɪəd/"}, {"english": "I did not sleep well.", "vietnamese": "Tôi ngủ không ngon.", "position": 28, "ipa": "/aɪ dɪdnˌɒt slˈiːp wˈɛl/"}, {"english": "I hope you feel better soon.", "vietnamese": "Tôi hy vọng bạn sớm thấy đỡ hơn.", "position": 29, "ipa": "/aɪ hˈəʊp juː fˈiːl bˈɛtə sˈuːn/"}, {"english": "It is good to talk to you.", "vietnamese": "Thật tốt khi được nói chuyện với bạn.", "position": 30, "ipa": "/ɪt ɪz ɡˈʊd tə tˈɔːk tə juː/"}], "grammar": "Dùng be + tính từ để nói cảm xúc; dùng because để nêu lý do ngắn.", "vocabulary_notes": "happy: vui; sad: buồn; tired: mệt; worried: lo lắng; excited: hào hứng", "title_vi": "Cảm xúc"},
{"title": "Lesson 19: Weekend Plans", "sentences": [{"english": "What are you going to do this weekend?", "vietnamese": "Bạn định làm gì vào cuối tuần này?", "position": 1, "ipa": "/wˌɒt ɑː juː ɡˌəʊɪŋ tə dˈuː ðɪs wiːkˈɛnd/"}, {"english": "I am going to visit my parents.", "vietnamese": "Tôi định đến thăm bố mẹ.", "position": 2, "ipa": "/aɪɐm ɡˌəʊɪŋ tə vˈɪzɪt maɪ pˈeəɹənts/"}, {"english": "We are going to have lunch together.", "vietnamese": "Chúng tôi định ăn trưa cùng nhau.", "position": 3, "ipa": "/wiː ɑː ɡˌəʊɪŋ tə hav lˈʌntʃ təɡˈɛðə/"}, {"english": "Are you free tomorrow?", "vietnamese": "Ngày mai bạn có rảnh không?", "position": 4, "ipa": "/ɑː juː fɹˈiː təmˈɒɹəʊ/"}, {"english": "Let us go to the park.", "vietnamese": "Chúng ta hãy đến công viên.", "position": 5, "ipa": "/lˈɛt ˌʌs ɡˌəʊ tə ðə pˈɑːk/"}, {"english": "That sounds good.", "vietnamese": "Nghe hay đấy.", "position": 6, "ipa": "/ðat sˈaʊndz ɡˈʊd/"}, {"english": "What time shall we meet?", "vietnamese": "Chúng ta gặp nhau lúc mấy giờ?", "position": 7, "ipa": "/wˌɒt tˈaɪm ʃˌal wiː mˈiːt/"}, {"english": "Let us meet at ten.", "vietnamese": "Chúng ta hãy gặp nhau lúc mười giờ.", "position": 8, "ipa": "/lˈɛt ˌʌs mˈiːt at tˈɛn/"}, {"english": "I cannot come on Saturday.", "vietnamese": "Tôi không thể đến vào thứ Bảy.", "position": 9, "ipa": "/aɪ kˈanɒt kˈʌm ˌɒn sˈatədˌeɪ/"}, {"english": "See you on Sunday.", "vietnamese": "Hẹn gặp bạn vào Chủ nhật.", "position": 10, "ipa": "/sˈiː juː ˌɒn sˈʌndeɪ/"}, {"english": "Do you have any plans for Sunday?", "vietnamese": "Bạn có kế hoạch gì cho Chủ nhật không?", "position": 11, "ipa": "/dˈuː juː hav ˌɛni plˈanz fɔː sˈʌndeɪ/"}, {"english": "I am going to stay at home.", "vietnamese": "Tôi định ở nhà.", "position": 12, "ipa": "/aɪɐm ɡˌəʊɪŋ tə stˈeɪ at hˈəʊm/"}, {"english": "We are going to watch a film.", "vietnamese": "Chúng tôi định xem phim.", "position": 13, "ipa": "/wiː ɑː ɡˌəʊɪŋ tə wˈɒtʃ ɐ fˈɪlm/"}, {"english": "Would you like to come with us?", "vietnamese": "Bạn có muốn đi cùng chúng tôi không?", "position": 14, "ipa": "/wʊd juː lˈaɪk tə kˈʌm wɪð ˌʌs/"}, {"english": "I would love to.", "vietnamese": "Tôi rất muốn.", "position": 15, "ipa": "/aɪ wʊd lˈʌv tuː/"}, {"english": "Sorry, I am busy that day.", "vietnamese": "Xin lỗi, hôm đó tôi bận.", "position": 16, "ipa": "/sˈɒɹi aɪɐm bˈɪzi ðat dˈeɪ/"}, {"english": "How about next weekend?", "vietnamese": "Cuối tuần sau thì sao?", "position": 17, "ipa": "/hˌaʊ ɐbˌaʊt nˈɛkst wiːkˈɛnd/"}, {"english": "That works for me.", "vietnamese": "Như vậy phù hợp với tôi.", "position": 18, "ipa": "/ðat wˈɜːks fɔː mˌiː/"}, {"english": "Where shall we meet?", "vietnamese": "Chúng ta gặp nhau ở đâu?", "position": 19, "ipa": "/wˌeə ʃˌal wiː mˈiːt/"}, {"english": "Let us meet outside the cafe.", "vietnamese": "Chúng ta hãy gặp nhau bên ngoài quán cà phê.", "position": 20, "ipa": "/lˈɛt ˌʌs mˈiːt aʊtsˈaɪd ðə kˈafeɪ/"}, {"english": "Can you bring some water?", "vietnamese": "Bạn có thể mang theo ít nước không?", "position": 21, "ipa": "/kan juː bɹˈɪŋ sˌʌm wˈɔːtə/"}, {"english": "I will bring some food.", "vietnamese": "Tôi sẽ mang theo ít đồ ăn.", "position": 22, "ipa": "/aɪ wɪl bɹˈɪŋ sˌʌm fˈuːd/"}, {"english": "What time are we leaving?", "vietnamese": "Chúng ta khởi hành lúc mấy giờ?", "position": 23, "ipa": "/wˌɒt tˈaɪm ɑː wiː lˈiːvɪŋ/"}, {"english": "We are leaving at eight.", "vietnamese": "Chúng ta khởi hành lúc tám giờ.", "position": 24, "ipa": "/wiː ɑː lˈiːvɪŋ at ˈeɪt/"}, {"english": "I am going to visit a museum.", "vietnamese": "Tôi định đến thăm bảo tàng.", "position": 25, "ipa": "/aɪɐm ɡˌəʊɪŋ tə vˈɪzɪt ɐ mjuːzˈiəm/"}, {"english": "The museum is open on Saturday.", "vietnamese": "Bảo tàng mở cửa vào thứ Bảy.", "position": 26, "ipa": "/ðə mjuːzˈiəm ɪz ˈəʊpən ˌɒn sˈatədˌeɪ/"}, {"english": "Let us check the weather.", "vietnamese": "Chúng ta hãy xem thời tiết.", "position": 27, "ipa": "/lˈɛt ˌʌs tʃˈɛk ðə wˈɛðə/"}, {"english": "Can we change the time?", "vietnamese": "Chúng ta có thể đổi giờ không?", "position": 28, "ipa": "/kan wiː tʃˈeɪndʒ ðə tˈaɪm/"}, {"english": "Please let me know.", "vietnamese": "Vui lòng báo cho tôi biết.", "position": 29, "ipa": "/plˈiːz lˈɛt mˌiː nˈəʊ/"}, {"english": "I am looking forward to it.", "vietnamese": "Tôi đang rất mong chờ điều đó.", "position": 30, "ipa": "/aɪɐm lˈʊkɪŋ fˈɔːwəd tʊ ɪt/"}], "grammar": "Dùng be going to + động từ nguyên mẫu để nói dự định; dùng Let us… để gợi ý.", "vocabulary_notes": "weekend: cuối tuần; visit: thăm; park: công viên; plan: kế hoạch; tomorrow: ngày mai", "title_vi": "Kế hoạch cuối tuần"},
{"title": "Lesson 20: Travel Essentials", "sentences": [{"english": "Where is the airport?", "vietnamese": "Sân bay ở đâu?", "position": 1, "ipa": "/wˌeəɹ ɪz ðɪ ˈeəpɔːt/"}, {"english": "I have my passport.", "vietnamese": "Tôi có mang hộ chiếu.", "position": 2, "ipa": "/aɪ hav maɪ pˈaspɔːt/"}, {"english": "Where can I check in?", "vietnamese": "Tôi có thể làm thủ tục ở đâu?", "position": 3, "ipa": "/wˌeə kan aɪ tʃˈɛk ˈɪn/"}, {"english": "Here is my ticket.", "vietnamese": "Đây là vé của tôi.", "position": 4, "ipa": "/hˈiəɹ ɪz maɪ tˈɪkɪt/"}, {"english": "I have one suitcase.", "vietnamese": "Tôi có một va li.", "position": 5, "ipa": "/aɪ hav wˈɒn sˈuːtkeɪs/"}, {"english": "What is the gate number?", "vietnamese": "Cửa ra máy bay là số mấy?", "position": 6, "ipa": "/wˌɒt ɪz ðə ɡˈeɪt nˈʌmbə/"}, {"english": "My flight leaves at two.", "vietnamese": "Chuyến bay của tôi khởi hành lúc hai giờ.", "position": 7, "ipa": "/maɪ flˈaɪt lˈiːvz at tˈuː/"}, {"english": "Where can I collect my luggage?", "vietnamese": "Tôi có thể nhận hành lý ở đâu?", "position": 8, "ipa": "/wˌeə kan aɪ kəlˈɛkt maɪ lˈʌɡɪdʒ/"}, {"english": "I am here on holiday.", "vietnamese": "Tôi đến đây để nghỉ dưỡng.", "position": 9, "ipa": "/aɪɐm hˈiəɹ ˌɒn hˈɒlɪdˌeɪ/"}, {"english": "I need a map of the city.", "vietnamese": "Tôi cần một bản đồ thành phố.", "position": 10, "ipa": "/aɪ nˈiːd ɐ mˈap ɒvðə sˈɪti/"}, {"english": "Is this the queue for check-in?", "vietnamese": "Đây có phải hàng chờ làm thủ tục không?", "position": 11, "ipa": "/ɪz ðɪs ðə kjˈuː fɔː tʃˈɛkˈɪn/"}, {"english": "Can I see your passport?", "vietnamese": "Cho tôi xem hộ chiếu của bạn được không?", "position": 12, "ipa": "/kan aɪ sˈiː jɔː pˈaspɔːt/"}, {"english": "Here is my passport.", "vietnamese": "Đây là hộ chiếu của tôi.", "position": 13, "ipa": "/hˈiəɹ ɪz maɪ pˈaspɔːt/"}, {"english": "Do you have any bags to check in?", "vietnamese": "Bạn có hành lý nào cần ký gửi không?", "position": 14, "ipa": "/dˈuː juː hav ˌɛni bˈaɡz tə tʃˈɛk ˈɪn/"}, {"english": "This is my hand luggage.", "vietnamese": "Đây là hành lý xách tay của tôi.", "position": 15, "ipa": "/ðɪs ɪz maɪ hˈand lˈʌɡɪdʒ/"}, {"english": "Can I have a window seat?", "vietnamese": "Tôi có thể ngồi cạnh cửa sổ không?", "position": 16, "ipa": "/kan aɪ hav ɐ wˈɪndəʊ sˈiːt/"}, {"english": "Where is the departure gate?", "vietnamese": "Cửa khởi hành ở đâu?", "position": 17, "ipa": "/wˌeəɹ ɪz ðə dɪpˈɑːtʃə ɡˈeɪt/"}, {"english": "Is the flight on time?", "vietnamese": "Chuyến bay có đúng giờ không?", "position": 18, "ipa": "/ɪz ðə flˈaɪt ˌɒn tˈaɪm/"}, {"english": "The flight is delayed.", "vietnamese": "Chuyến bay bị hoãn.", "position": 19, "ipa": "/ðə flˈaɪt ɪz dɪlˈeɪd/"}, {"english": "What time does boarding start?", "vietnamese": "Mấy giờ bắt đầu lên máy bay?", "position": 20, "ipa": "/wˌɒt tˈaɪm dˈʌz bˈɔːdɪŋ stˈɑːt/"}, {"english": "Please keep your ticket ready.", "vietnamese": "Vui lòng chuẩn bị sẵn vé.", "position": 21, "ipa": "/plˈiːz kˈiːp jɔː tˈɪkɪt ɹˈɛdi/"}, {"english": "Where is passport control?", "vietnamese": "Khu kiểm soát hộ chiếu ở đâu?", "position": 22, "ipa": "/wˌeəɹ ɪz pˈaspɔːt kəntɹˈəʊl/"}, {"english": "How long are you staying?", "vietnamese": "Bạn sẽ ở lại bao lâu?", "position": 23, "ipa": "/hˌaʊ lˈɒŋ ɑː juː stˈeɪɪŋ/"}, {"english": "I am staying for one week.", "vietnamese": "Tôi sẽ ở lại một tuần.", "position": 24, "ipa": "/aɪɐm stˈeɪɪŋ fɔː wˈɒn wˈiːk/"}, {"english": "I am staying at a hotel.", "vietnamese": "Tôi sẽ ở khách sạn.", "position": 25, "ipa": "/aɪɐm stˈeɪɪŋ atə həʊtˈɛl/"}, {"english": "Where can I change money?", "vietnamese": "Tôi có thể đổi tiền ở đâu?", "position": 26, "ipa": "/wˌeə kan aɪ tʃˈeɪndʒ mˈʌni/"}, {"english": "My suitcase is missing.", "vietnamese": "Va li của tôi bị thất lạc.", "position": 27, "ipa": "/maɪ sˈuːtkeɪs ɪz mˈɪsɪŋ/"}, {"english": "It is a large black suitcase.", "vietnamese": "Đó là một chiếc va li lớn màu đen.", "position": 28, "ipa": "/ɪt ɪz ɐ lˈɑːdʒ blˈak sˈuːtkeɪs/"}, {"english": "Can you help me find it?", "vietnamese": "Bạn có thể giúp tôi tìm nó không?", "position": 29, "ipa": "/kan juː hˈɛlp mˌiː fˈaɪnd ɪt/"}, {"english": "I need a taxi to the hotel.", "vietnamese": "Tôi cần taxi đến khách sạn.", "position": 30, "ipa": "/aɪ nˈiːd ɐ tˈaksi tə ðə həʊtˈɛl/"}], "grammar": "Dùng I need… để nói nhu cầu và Where can I…? để hỏi nơi thực hiện việc gì.", "vocabulary_notes": "passport: hộ chiếu; airport: sân bay; flight: chuyến bay; luggage: hành lý; gate: cửa ra máy bay", "title_vi": "Giao tiếp khi đi du lịch"},
{"title": "Lesson 21: At a Hotel", "sentences": [{"english": "I have a reservation.", "vietnamese": "Tôi đã đặt phòng.", "position": 1, "ipa": "/aɪ hav ɐ ɹˌɛzəvˈeɪʃən/"}, {"english": "My name is Mikey.", "vietnamese": "Tên tôi là Mikey.", "position": 2, "ipa": "/maɪ nˈeɪm ɪz mˈaɪki/"}, {"english": "I would like a room for two nights.", "vietnamese": "Tôi muốn đặt một phòng trong hai đêm.", "position": 3, "ipa": "/aɪ wʊd lˈaɪk ɐ ɹˈuːm fɔː tˈuː nˈaɪts/"}, {"english": "Is breakfast included?", "vietnamese": "Giá phòng đã bao gồm bữa sáng chưa?", "position": 4, "ipa": "/ɪz bɹˈɛkfəst ɪŋklˈuːdɪd/"}, {"english": "What time is breakfast?", "vietnamese": "Bữa sáng bắt đầu lúc mấy giờ?", "position": 5, "ipa": "/wˌɒt tˈaɪm ɪz bɹˈɛkfəst/"}, {"english": "Can I have the room key, please?", "vietnamese": "Cho tôi xin chìa khóa phòng được không?", "position": 6, "ipa": "/kan aɪ hav ðə ɹˈuːm kˈiː plˈiːz/"}, {"english": "Is there Wi-Fi in the room?", "vietnamese": "Trong phòng có Wi-Fi không?", "position": 7, "ipa": "/ɪz ðeə wˈaɪfˌaɪ ɪnðə ɹˈuːm/"}, {"english": "What is the Wi-Fi password?", "vietnamese": "Mật khẩu Wi-Fi là gì?", "position": 8, "ipa": "/wˌɒt ɪz ðə wˈaɪfˌaɪ pˈaswɜːd/"}, {"english": "The air conditioner is not working.", "vietnamese": "Máy điều hòa không hoạt động.", "position": 9, "ipa": "/ðɪ ˈeə kəndˈɪʃənəɹ ɪz nˌɒt wˈɜːkɪŋ/"}, {"english": "I would like to check out.", "vietnamese": "Tôi muốn trả phòng.", "position": 10, "ipa": "/aɪ wʊd lˈaɪk tə tʃˈɛk ˈaʊt/"}, {"english": "Can I check in now?", "vietnamese": "Tôi có thể nhận phòng bây giờ không?", "position": 11, "ipa": "/kan aɪ tʃˈɛk ɪn nˈaʊ/"}, {"english": "The reservation is under my name.", "vietnamese": "Phòng được đặt dưới tên của tôi.", "position": 12, "ipa": "/ðə ɹˌɛzəvˈeɪʃən ɪz ˌʌndə maɪ nˈeɪm/"}, {"english": "Can I see your ID, please?", "vietnamese": "Cho tôi xem giấy tờ tùy thân được không?", "position": 13, "ipa": "/kan aɪ sˈiː jɔːɹ aɪdˈiː plˈiːz/"}, {"english": "Here is my ID.", "vietnamese": "Đây là giấy