se": "Giá phòng mỗi đêm là bao nhiêu?", "position": 28, "ipa": "/hˌaʊ mˈʌtʃ ɪz ðə ɹˈuːm pɜː nˈaɪt/"}, {"english": "Thank you for a pleasant stay.", "vietnamese": "Cảm ơn bạn vì kỳ nghỉ dễ chịu.", "position": 29, "ipa": "/θˈaŋk juː fəɹə plˈɛzənt stˈeɪ/"}, {"english": "I enjoyed staying here.", "vietnamese": "Tôi rất thích thời gian ở đây.", "position": 30, "ipa": "/aɪ ɛndʒˈɔɪd stˈeɪɪŋ hˈiə/"}], "grammar": "Dùng I have… để xác nhận đặt phòng; dùng Is there…? để hỏi tiện ích.", "vocabulary_notes": "reservation: đặt phòng; room: phòng; key: chìa khóa; breakfast: bữa sáng; check out: trả phòng", "title_vi": "Tại khách sạn"},
{"title": "Lesson 22: Asking for Help", "sentences": [{"english": "Excuse me, can you help me?", "vietnamese": "Xin lỗi, bạn có thể giúp tôi không?", "position": 1, "ipa": "/ɛkskjˈuːs mˌiː kan juː hˈɛlp mˌiː/"}, {"english": "I am lost.", "vietnamese": "Tôi bị lạc đường.", "position": 2, "ipa": "/aɪɐm lˈɒst/"}, {"english": "I cannot find my phone.", "vietnamese": "Tôi không tìm thấy điện thoại.", "position": 3, "ipa": "/aɪ kˈanɒt fˈaɪnd maɪ fˈəʊn/"}, {"english": "Can I use your phone?", "vietnamese": "Tôi có thể dùng điện thoại của bạn không?", "position": 4, "ipa": "/kan aɪ jˈuːz jɔː fˈəʊn/"}, {"english": "Please call my friend.", "vietnamese": "Vui lòng gọi bạn tôi.", "position": 5, "ipa": "/plˈiːz kˈɔːl maɪ fɹˈɛnd/"}, {"english": "I do not speak English very well.", "vietnamese": "Tôi nói tiếng Anh chưa tốt lắm.", "position": 6, "ipa": "/aɪ duːnˌɒt spˈiːk ˈɪŋɡlɪʃ vˈɛɹi wˈɛl/"}, {"english": "Can you write it down, please?", "vietnamese": "Bạn có thể viết điều đó ra không?", "position": 7, "ipa": "/kan juː ɹˈaɪt ɪt dˈaʊn plˈiːz/"}, {"english": "Please show me what to do.", "vietnamese": "Vui lòng chỉ cho tôi phải làm gì.", "position": 8, "ipa": "/plˈiːz ʃˈəʊ mˌiː wɒt tə dˈuː/"}, {"english": "It is an emergency.", "vietnamese": "Đây là tình huống khẩn cấp.", "position": 9, "ipa": "/ɪt ɪz ɐn ɪmˈɜːdʒənsi/"}, {"english": "Thank you for helping me.", "vietnamese": "Cảm ơn bạn đã giúp tôi.", "position": 10, "ipa": "/θˈaŋk juː fɔː hˈɛlpɪŋ mˌiː/"}, {"english": "Could you speak more slowly?", "vietnamese": "Bạn có thể nói chậm hơn không?", "position": 11, "ipa": "/kʊd juː spˈiːk mˈɔː slˈəʊli/"}, {"english": "I need some help with this form.", "vietnamese": "Tôi cần giúp điền mẫu đơn này.", "position": 12, "ipa": "/aɪ nˈiːd sˌʌm hˈɛlp wɪð ðɪs fˈɔːm/"}, {"english": "What should I write here?", "vietnamese": "Tôi nên viết gì ở đây?", "position": 13, "ipa": "/wˌɒt ʃˌʊd aɪ ɹˈaɪt hˈiə/"}, {"english": "Where can I get help?", "vietnamese": "Tôi có thể tìm sự giúp đỡ ở đâu?", "position": 14, "ipa": "/wˌeə kan aɪ ɡɛt hˈɛlp/"}, {"english": "I have lost my wallet.", "vietnamese": "Tôi bị mất ví.", "position": 15, "ipa": "/aɪ hav lˈɒst maɪ wˈɒlɪt/"}, {"english": "Is there a lost property office?", "vietnamese": "Ở đây có phòng giữ đồ thất lạc không?", "position": 16, "ipa": "/ɪz ðeəɹ ɐ lˈɒst pɹˈɒpəti ˈɒfɪs/"}, {"english": "Please wait a moment.", "vietnamese": "Vui lòng chờ một lát.", "position": 17, "ipa": "/plˈiːz wˈeɪt ɐ mˈəʊmənt/"}, {"english": "Can you show me the way?", "vietnamese": "Bạn có thể chỉ đường cho tôi không?", "position": 18, "ipa": "/kan juː ʃˈəʊ mˌiː ðə wˈeɪ/"}, {"english": "I cannot open this door.", "vietnamese": "Tôi không mở được cửa này.", "position": 19, "ipa": "/aɪ kˈanɒt ˈəʊpən ðɪs dˈɔː/"}, {"english": "Can you carry this bag for me?", "vietnamese": "Bạn có thể mang giúp tôi chiếc túi này không?", "position": 20, "ipa": "/kan juː kˈaɹi ðɪs bˈaɡ fɔː mˌiː/"}, {"english": "I need to charge my phone.", "vietnamese": "Tôi cần sạc điện thoại.", "position": 21, "ipa": "/aɪ nˈiːd tə tʃˈɑːdʒ maɪ fˈəʊn/"}, {"english": "Do you have a charger?", "vietnamese": "Bạn có bộ sạc không?", "position": 22, "ipa": "/dˈuː juː hav ɐ tʃˈɑːdʒə/"}, {"english": "Can I sit here for a moment?", "vietnamese": "Tôi có thể ngồi đây một lát không?", "position": 23, "ipa": "/kan aɪ sˈɪt hˈiə fəɹə mˈəʊmənt/"}, {"english": "Please stay with me.", "vietnamese": "Vui lòng ở lại với tôi.", "position": 24, "ipa": "/plˈiːz stˈeɪ wɪð mˌiː/"}, {"english": "I need to contact the police.", "vietnamese": "Tôi cần liên hệ với cảnh sát.", "position": 25, "ipa": "/aɪ nˈiːd tə kˈɒntakt ðə pəlˈiːs/"}, {"english": "Please call an ambulance.", "vietnamese": "Vui lòng gọi xe cứu thương.", "position": 26, "ipa": "/plˈiːz kˈɔːl ɐn ˈambjʊləns/"}, {"english": "Can you tell me your location?", "vietnamese": "Bạn có thể cho tôi biết vị trí của bạn không?", "position": 27, "ipa": "/kan juː tˈɛl mˌiː jɔː ləʊkˈeɪʃən/"}, {"english": "I am outside the main entrance.", "vietnamese": "Tôi đang ở bên ngoài lối vào chính.", "position": 28, "ipa": "/aɪɐm aʊtsˈaɪd ðə mˈeɪn ˈɛntɹəns/"}, {"english": "Help is on the way.", "vietnamese": "Người hỗ trợ đang đến.", "position": 29, "ipa": "/hˈɛlp ɪz ɒnðə wˈeɪ/"}, {"english": "I really appreciate your help.", "vietnamese": "Tôi rất biết ơn sự giúp đỡ của bạn.", "position": 30, "ipa": "/aɪ ɹˈiəlɪ ɐpɹˈiːʃɪˌeɪt jɔː hˈɛlp/"}], "grammar": "Dùng Can you help me? và I need…; dùng please để yêu cầu lịch sự.", "vocabulary_notes": "help: giúp đỡ; lost: lạc đường; phone: điện thoại; understand: hiểu; emergency: tình huống khẩn cấp", "title_vi": "Nhờ giúp đỡ"}
]
$upgrade_data$::jsonb;
  topic jsonb;
  sentence jsonb;
  target_id bigint;
  candidate_count integer;
  sentence_count integer;
  column_name_to_add text;
  extra_columns text := '';
  extra_values text := '';
  added integer := 0;
  affected integer;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('mikey-a1-topics-v1'));
  FOREACH column_name_to_add IN ARRAY ARRAY['sentence_order', 'order_index', 'ipa', 'vocabulary_notes', 'grammar_explanation', 'context_of_use'] LOOP
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name='sentences' AND column_name=column_name_to_add
    ) THEN
      extra_columns := extra_columns || ', ' || quote_ident(column_name_to_add);
      extra_values := extra_values || CASE column_name_to_add
        WHEN 'sentence_order' THEN ', $4'
        WHEN 'order_index' THEN ', $4'
        WHEN 'ipa' THEN ', $5'
        WHEN 'vocabulary_notes' THEN ', $6'
        WHEN 'grammar_explanation' THEN ', $7'
        ELSE ', $8' END;
    END IF;
  END LOOP;
  FOR topic IN SELECT value FROM jsonb_array_elements(lesson_data) LOOP
    SELECT count(*), min(id) INTO candidate_count, target_id
    FROM public.lessons WHERE course_id=1 AND title=topic->>'title'
      AND strpos(coalesce(description,''),'mikey-a1-topics-v1')>0;
    IF candidate_count <> 1 THEN
      RAISE EXCEPTION 'Cannot identify exact imported topic %. Nothing changed.', topic->>'title';
    END IF;
    IF EXISTS (SELECT 1 FROM public.sentences WHERE lesson_id=target_id GROUP BY english HAVING count(*)>1) THEN
      RAISE EXCEPTION 'Duplicate sentences already exist in %. Nothing changed.', topic->>'title';
    END IF;
    -- Refuse to silently reintroduce or overwrite teacher-edited sentences.
    IF EXISTS (
      SELECT 1 FROM public.sentences existing WHERE existing.lesson_id=target_id
      AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(topic->'sentences') expected WHERE expected->>'english'=existing.english)
    ) THEN
      RAISE EXCEPTION 'Teacher-edited content in %. Review a mapping before importing. Nothing changed.', topic->>'title';
    END IF;
    FOR sentence IN SELECT value FROM jsonb_array_elements(topic->'sentences') LOOP
      EXECUTE 'INSERT INTO public.sentences (lesson_id, english, vietnamese' || extra_columns ||
        ') SELECT $1, $2, $3' || extra_values ||
        ' WHERE NOT EXISTS (SELECT 1 FROM public.sentences WHERE lesson_id=$1 AND english=$2)'
      USING target_id, sentence->>'english', sentence->>'vietnamese',
        (sentence->>'position')::integer, sentence->>'ipa', topic->>'vocabulary_notes',
        topic->>'grammar', topic->>'title_vi';
      GET DIAGNOSTICS affected = ROW_COUNT;
      added := added + affected;
    END LOOP;
    SELECT count(*) INTO sentence_count FROM public.sentences WHERE lesson_id=target_id;
    IF sentence_count <> 30 THEN
      RAISE EXCEPTION 'Unexpected count in %: %. Nothing changed.', topic->>'title', sentence_count;
    END IF;
  END LOOP;
  RAISE NOTICE 'Added % sentences. Existing IDs and learning progress were preserved.', added;
END;
$upgrade$;
COMMIT;
SELECT l.id, l.title, l.status, count(s.id) AS sentence_count
FROM public.lessons l LEFT JOIN public.sentences s ON s.lesson_id=l.id
WHERE l.course_id=1 AND strpos(coalesce(l.description,''),'mikey-a1-topics-v1')>0
GROUP BY l.id,l.title,l.status,l.order_index ORDER BY l.order_index;
